AGENT_STATUS_LABELS = {
    "orchestrator": "总调度",
    "context_ready": "上下文就绪",
    "one_shot": "单轮生成",
    "tool_ready": "工具就绪",
    "implemented": "已接入",
    "proxy_agent": "代理已接入",
    "planned": "规划中",
}


def project_link_summary(project_id: str) -> dict[str, list[dict[str, str]]]:
    inbound = [edge for edge in PROJECT_LINKS if edge["to"] == project_id]
    outbound = [edge for edge in PROJECT_LINKS if edge["from"] == project_id]
    return {"inbound": inbound, "outbound": outbound}


def agent_display_name(project_id: str) -> str:
    """Return the user-facing Chinese name while keeping project IDs internal."""
    capability = AGENT_REGISTRY.get(project_id, {})
    if capability.get("name"):
        return str(capability["name"])
    project = next((item for item in load_projects() if item.get("id") == project_id), {})
    return f"{project.get('title', project_id)} Agent"


def agent_status_label(status: str) -> str:
    return AGENT_STATUS_LABELS.get(status, status or "未定义")


def project_href(project_id: str) -> str:
    if project_id == "workbench":
        return "/"
    project = next((item for item in load_projects() if item.get("id") == project_id), {})
    return str(project.get("href") or f"/projects/{project_id}")


def public_project_link(edge: dict[str, str]) -> dict[str, str]:
    """Add user-facing names and URLs without changing the internal edge shape."""
    source = edge.get("from", "")
    target = edge.get("to", "")
    return {
        **edge,
        "from_name": agent_display_name(source),
        "to_name": agent_display_name(target),
        "from_href": project_href(source),
        "to_href": project_href(target),
    }


def agent_detail(project_id: str, *, llm_ready: bool | None = None) -> dict[str, Any]:
    capability = AGENT_REGISTRY.get(project_id, {})
    tools = list(capability.get("tools", []))
    if project_id != "workbench":
        tools = list(dict.fromkeys([*tools, "work_item_read", "work_item_run"]))
    # 所有项目 Agent 统一具备公网只读调研能力（web_search 搜索 / web_fetch 抓正文）。
    # 与 SUBAGENT_TOOL_MAP 保持一致：能力声明、总调度工具边界和前端能力列表
    # 不能各自为政，否则文档 Agent 写调研文档时只能"声称交接"而交接又不落地。
    tools = list(dict.fromkeys([*tools, "web_search", "web_fetch"]))
    detail = {
        "project_id": project_id,
        "name": agent_display_name(project_id),
        "status": capability.get("status", "planned"),
        "status_label": agent_status_label(capability.get("status", "planned")),
        "kind": capability.get("kind", "unknown"),
        "tools": tools,
        "rounds": capability.get("rounds", []),
        "next": capability.get("next", "建立项目 Agent 能力定义"),
    }
    implementation = AGENT_IMPLEMENTATIONS.get(project_id, {})
    detail["implemented_tools"] = implementation.get("implemented", [])
    detail["gaps"] = implementation.get("gaps", [])
    detail["links"] = project_link_summary(project_id)
    playbook = AGENT_PLAYBOOKS.get(project_id, {})
    detail["mission"] = playbook.get("mission", "围绕项目上下文给出可执行结果")
    detail["output_contract"] = playbook.get("output", ["结论", "证据", "下一步", "风险"])
    detail["autonomy"] = playbook.get("autonomy", "只读分析；写入动作按权限确认")
    permissions = []
    for tool in tools:
        policy = AGENT_TOOL_POLICIES.get(tool)
        if policy:
            permissions.append({"tool": tool, **policy})
        else:
            permissions.append(
                {
                    "tool": tool,
                    "label": tool,
                    "mode": "unavailable",
                    "risk": "unknown",
                    "enabled": False,
                    "description": "已声明但尚未接入执行器，Agent 不会假装调用。",
                }
            )
    detail["tool_permissions"] = permissions
    detail["tool_permission_summary"] = {
        "readonly": sum(1 for item in permissions if item["mode"] == "readonly"),
        "auto": sum(1 for item in permissions if item["mode"] == "auto"),
        "restricted": sum(1 for item in permissions if item["mode"] == "restricted"),
        "confirm": sum(1 for item in permissions if item["mode"] == "confirm"),
        "unavailable": sum(1 for item in permissions if not item["enabled"]),
    }
    detail["run_summary"] = agent_run_summary(project_id)
    if llm_ready is not None:
        detail["llm_ready"] = llm_ready
    return detail


AUDIT_STATUS_LABELS = {
    "verified": "已验证",
    "synthetic": "仅合成验收",
    "legacy": "历史未分类",
    "observed": "有运行记录",
    "partial": "部分验证",
    "configured": "仅配置未验证",
    "blocked": "能力被阻断",
    "failed": "失败待修复",
    "missing": "暂无数据",
    "fresh": "数据新鲜",
    "aging": "数据较旧",
    "stale": "数据已过期",
}


def _audit_datetime(value: Any) -> datetime | None:
    """Parse the few timestamp shapes used by local snapshots and SQLite."""
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            return datetime.fromtimestamp(float(value), tz=timezone.utc)
        except (OverflowError, OSError, ValueError):
            return None
    text = str(value or "").strip()
    if not text:
        return None
    normalized = text.replace("Z", "+00:00")
    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError:
        parsed = None
        for pattern in ("%Y/%m/%d %H:%M", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
            try:
                parsed = datetime.strptime(text, pattern)
                break
            except ValueError:
                continue
    if parsed is None:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def audit_freshness(timestamp: Any, source: str = "", detail: str = "") -> dict[str, Any]:
    checked_at = str(timestamp or "")
    parsed = _audit_datetime(timestamp)
    age_seconds = max(0, int((datetime.now(timezone.utc) - parsed).total_seconds())) if parsed else None
    if parsed is None:
        status = "missing"
        label = "没有可用数据时间"
    elif age_seconds is not None and age_seconds <= 6 * 3600:
        status = "fresh"
        label = "数据新鲜"
    elif age_seconds is not None and age_seconds <= 24 * 3600:
        status = "aging"
        label = "数据较旧"
    else:
        status = "stale"
        label = "数据已过期"
    return {
        "status": status,
        "status_label": AUDIT_STATUS_LABELS.get(status, status),
        "label": label,
        "checked_at": checked_at,
        "age_seconds": age_seconds,
        "source": source,
        "detail": detail,
    }


def project_data_freshness(project_id: str) -> dict[str, Any]:
    """Expose the source timestamp an Agent is actually using right now."""
    timestamp = ""
    source = "本地 SQLite"
    detail = ""
    if project_id == "sub2api":
        snapshot = load_sub2api_snapshot()
        timestamp = snapshot.get("checked_at") or snapshot.get("fetched_at", "")
        source = "Sub2API 脱敏快照"
        detail = (analyze_sub2api_snapshot(snapshot).get("status_label") or "账户快照")
    elif project_id == "market":
        snapshot = load_market_snapshot()
        timestamp = snapshot.get("checked_at", "")
        source = str(snapshot.get("source") or "公开行情快照")
        detail = f"{len(snapshot.get('quotes') or [])} 个报价"
    elif project_id == "server":
        snapshot = load_server_monitor_snapshot()
        timestamp = snapshot.get("checked_at", "")
        source = "服务器只读监控快照"
        detail = str(snapshot.get("status") or "未检查")
    elif project_id == "aihot":
        snapshot = load_aihot_snapshot()
        timestamp = snapshot.get("fetched_at", "")
        source = "aihot.today 资讯快照"
        detail = f"{len(snapshot.get('items') or [])} 条资讯"
    elif project_id == "cid-dashboard":
        snapshot = list_cid_dashboard_snapshots(limit=1)
        latest = snapshot[0] if snapshot else {}
        timestamp = latest.get("fetched_at", "")
        source = "独立开发者看板快照"
        detail = f"{latest.get('project_count', 0)} 个项目" if latest else "尚未保存快照"
    elif project_id == "knowledge":
        status = obsidian_status()
        timestamp = status.get("last_indexed_at") or (status.get("last_scan") or {}).get("scanned_at", "")
        source = "Obsidian 本地索引"
        detail = f"{status.get('note_count', 0)} 篇笔记"
    elif project_id == "doc-factory":
        paths = [path for path in OUTPUTS_DIR.iterdir() if path.is_file() and not path.name.startswith(".")]
        latest = max(paths, key=lambda path: path.stat().st_mtime, default=None)
        timestamp = latest.stat().st_mtime if latest else ""
        source = "工作台输出目录"
        detail = latest.name if latest else "尚未生成产物"
    elif project_id == "inbox":
        connection = db_connection()
        try:
            row = connection.execute("SELECT updated_at FROM inbox ORDER BY updated_at DESC, id DESC LIMIT 1").fetchone()
            timestamp = row["updated_at"] if row else ""
        finally:
            connection.close()
        source = "本地收件箱"
        detail = f"{len(list_inbox('inbox'))} 条待处理"
    elif project_id == "product-manager":
        connection = db_connection()
        try:
            row = connection.execute(
                """SELECT MAX(updated_at) AS updated_at FROM (
                    SELECT updated_at FROM product_feedback
                    UNION ALL SELECT updated_at FROM product_requirements
                    UNION ALL SELECT updated_at FROM product_decisions
                )"""
            ).fetchone()
            timestamp = row["updated_at"] if row and row["updated_at"] else ""
        finally:
            connection.close()
        overview = product_manager_overview()
        source = "产品作战室 SQLite"
        detail = f"{overview['summary']['feedback_total']} 条反馈 · {overview['summary']['requirements_total']} 个需求"
    else:
        latest = (agent_run_summary(project_id).get("latest") or {})
        timestamp = latest.get("updated_at") or latest.get("created_at", "")
        source = "Agent Run"
        detail = latest.get("title", "尚未运行")
    return audit_freshness(timestamp, source, detail)


def project_link_audit(edge: dict[str, str]) -> dict[str, Any]:
    """Check whether a configured edge has produced the objects in its contract."""
    source_project = edge.get("from", "")
    target_project = edge.get("to", "")
    work_items = [
        item
        for item in list_work_items(project_id=source_project)
        if target_project in {part.strip() for part in str(item.get("target_project", "")).split(",") if part.strip()}
    ]
    work_item_ids = {str(item.get("id")) for item in work_items}
    relations = list_relations()
    matched_relations = []
    for relation in relations:
        metadata = relation.get("metadata") if isinstance(relation.get("metadata"), dict) else {}
        related_ids = {str(relation.get("from_id", "")), str(relation.get("to_id", ""))}
        metadata_projects = {
            str(metadata.get("source_project") or ""),
            str(metadata.get("from_project") or ""),
            str(metadata.get("target_project") or ""),
            str(metadata.get("to_project") or ""),
            str(metadata.get("project_id") or ""),
        }
        if work_item_ids.intersection(related_ids) or target_project in metadata_projects and source_project in metadata_projects:
            matched_relations.append(relation)
        elif relation.get("from_type") == "project" and relation.get("from_id") == source_project and target_project in metadata_projects:
            matched_relations.append(relation)
    relation_ids = {str(relation.get("id")) for relation in matched_relations}
    target_runs = []
    for run in list_agent_runs(target_project, limit=100):
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        result = run.get("result") if isinstance(run.get("result"), dict) else {}
        referenced_item = str(request.get("work_item_id") or result.get("work_item_id") or "")
        if referenced_item in work_item_ids:
            target_runs.append(run)
            continue
        if any(str(relation.get("to_id")) == str(run.get("id")) for relation in matched_relations if relation.get("to_type") == "agent_run"):
            target_runs.append(run)
    run_ids = {str(run.get("id")) for run in target_runs}
    notifications = []
    for notification in list_notifications(limit=100):
        event_key = str(notification.get("event_key") or "")
        if notification.get("project_id") == target_project and (
            any(item_id and item_id in event_key for item_id in work_item_ids)
            or any(run_id and run_id in event_key for run_id in run_ids)
        ):
            notifications.append(notification)
    stages = {
        "work_item": bool(work_items),
        "relation": bool(matched_relations),
        "target_run": bool(target_runs),
        "notification": bool(notifications),
    }
    score = sum(stages.values())
    evidence_summary = evidence_edge_summary(f"{source_project}->{target_project}")
    if score == 4 and evidence_summary.get("business_status") == "verified":
        status = "verified"
    elif score == 4 and evidence_summary.get("business_status") == "synthetic_only":
        # A deterministic acceptance run proves that the harness works, not
        # that this edge has carried a real business object recently.
        status = "synthetic"
    elif score == 4 and evidence_summary.get("business_status") == "legacy_unclassified":
        status = "legacy"
    else:
        status = "partial" if score else "configured"
    return {
        **public_project_link(edge),
        "status": status,
        "status_label": AUDIT_STATUS_LABELS[status],
        "score": score,
        "stages": stages,
        "evidence_summary": evidence_summary,
        "evidence": {
            "work_items": len(work_items),
            "relations": len(matched_relations),
            "target_runs": len(target_runs),
            "notifications": len(notifications),
            "work_item_ids": [item.get("id") for item in work_items[:6]],
            "run_ids": [run.get("id") for run in target_runs[:6]],
            "relation_ids": list(relation_ids)[:6],
        },
    }


def evidence_edge_summary(edge_key: str) -> dict[str, Any]:
    """Summarize persisted evidence without treating synthetic checks as business proof."""
    connection = db_connection()
    try:
        rows = connection.execute(
            "SELECT scenario, status, run_id, detail_json, created_at FROM evidence_checks WHERE edge_key = ? ORDER BY created_at DESC, id DESC",
            (edge_key,),
        ).fetchall()
    finally:
        connection.close()
    records = []
    for row in rows:
        detail = platform_decode_json(row["detail_json"], {})
        records.append({
            "scenario": row["scenario"],
            "status": row["status"],
            "run_id": row["run_id"],
            "detail": detail if isinstance(detail, dict) else {},
            "created_at": row["created_at"],
        })
    verified = [item for item in records if item["status"] == "verified"]
    for item in verified:
        item["verification_kind"] = evidence_verification_kind(item["detail"])
    synthetic = [item for item in verified if item["verification_kind"] == "synthetic_acceptance"]
    business = [item for item in verified if item["verification_kind"] == "business_execution"]
    legacy = [item for item in verified if item["verification_kind"] == "legacy_unclassified"]
    latest_business = business[0] if business else None
    return {
        "total": len(records),
        "verified": len(verified),
        "pending": sum(1 for item in records if item["status"] == "pending"),
        "synthetic_verified": len(synthetic),
        "business_verified": len(business),
        "legacy_unclassified_verified": len(legacy),
        "business_status": "verified" if business else "synthetic_only" if synthetic else "legacy_unclassified" if legacy else "pending",
        "latest_business_execution": {
            "scenario": latest_business["scenario"],
            "run_id": latest_business["run_id"] or latest_business["detail"].get("run_id", ""),
            "work_item_id": latest_business["detail"].get("work_item_id", ""),
            "verified_at": latest_business["detail"].get("verified_at") or latest_business["created_at"],
        } if latest_business else None,
        "policy": "synthetic_acceptance 只证明验收工具跑通；business_execution 才是线上真实业务对象链。",
    }


def evidence_verification_kind(detail: dict[str, Any] | None) -> str:
    """Return the persisted evidence class without guessing business success."""
    payload = detail if isinstance(detail, dict) else {}
    kind = str(payload.get("verification_kind") or "").strip()
    if kind in {"synthetic_acceptance", "business_execution", "legacy_unclassified"}:
        return kind
    if payload.get("synthetic") is True:
        return "synthetic_acceptance"
    return "legacy_unclassified"


def reclassify_legacy_evidence(connection: sqlite3.Connection) -> int:
    """Persist an explicit class for old verified rows, idempotently.

    Older releases recorded only ``verified`` and an object-chain note.  Those
    rows remain useful history, but cannot be promoted to business evidence
    without a real execution marker.  A timestamp is stored so a later real
    WorkItem/Run can replace the legacy classification once, while repeated
    reads do not mutate the record again.
    """
    timestamp = now_iso()
    rows = connection.execute(
        "SELECT id, detail_json FROM evidence_checks WHERE status = 'verified'"
    ).fetchall()
    changed = 0
    for row in rows:
        detail = platform_decode_json(row["detail_json"], {})
        if not isinstance(detail, dict):
            detail = {}
        if str(detail.get("verification_kind") or "").strip() in {"synthetic_acceptance", "business_execution", "legacy_unclassified"}:
            continue
        detail["verification_kind"] = evidence_verification_kind(detail)
        detail["classification_source"] = "legacy_record_reclassification"
        detail["reclassified_at"] = timestamp
        connection.execute(
            "UPDATE evidence_checks SET detail_json = ? WHERE id = ?",
            (json.dumps(detail, ensure_ascii=False), row["id"]),
        )
        changed += 1
    return changed


def evidence_record_timestamp(record: dict[str, Any]) -> datetime | None:
    """Find the newest timestamp carried by a WorkItem/Run evidence record."""
    values = []
    for key in ("created_at", "updated_at", "started_at", "finished_at"):
        parsed = _audit_datetime(record.get(key))
        if parsed:
            values.append(parsed)
    return max(values) if values else None


def project_audit(project_id: str = "") -> dict[str, Any]:
    project_ids = [project_id] if project_id else [item.get("id") for item in load_projects() if item.get("id") in AGENT_REGISTRY]
    configured = bool(llm_settings()["configured"])
    link_rows = [project_link_audit(edge) for edge in PROJECT_LINKS]
    inbound_by_project: dict[str, list[dict[str, Any]]] = {}
    outbound_by_project: dict[str, list[dict[str, Any]]] = {}
    for link in link_rows:
        outbound_by_project.setdefault(link.get("from", ""), []).append(link)
        inbound_by_project.setdefault(link.get("to", ""), []).append(link)
    agents = []
    for current_id in project_ids:
        if current_id not in AGENT_REGISTRY:
            continue
        detail = agent_detail(current_id, llm_ready=configured)
        summary = detail.get("run_summary") or {}
        quality = agent_quality_metrics(current_id, 24)
        latest = summary.get("latest") or {}
        tool_checks = []
        declared_tools = detail.get("tools") or []
        for tool in declared_tools:
            policy = AGENT_TOOL_POLICIES.get(tool)
            available = bool(policy and policy.get("enabled"))
            reason = "" if available else "工具策略未接入"
            if tool == "global_llm" and not configured:
                available = False
                reason = "尚未配置全局 LLM"
            tool_checks.append({
                "tool": tool,
                "label": policy.get("label", tool) if policy else tool,
                "mode": policy.get("mode", "unavailable") if policy else "unavailable",
                "enabled": available,
                "status": "ready" if available else "blocked",
                "reason": reason,
            })
        if latest.get("status") == "failed":
            run_status = "failed"
        elif summary.get("total", 0):
            run_status = "observed"
        elif any(item["status"] == "blocked" for item in tool_checks):
            run_status = "blocked"
        else:
            run_status = "configured"
        agents.append({
            "project_id": current_id,
            "name": detail.get("name"),
            "status": detail.get("status"),
            "status_label": detail.get("status_label"),
            "audit_status": run_status,
            "audit_status_label": AUDIT_STATUS_LABELS[run_status],
            "implementation": {"implemented": detail.get("implemented_tools", []), "gaps": detail.get("gaps", [])},
            "tool_checks": tool_checks,
            "run_summary": summary,
            "quality": quality,
            "latest_run": latest,
            "activity": project_activity(current_id),
            "freshness": project_data_freshness(current_id),
            "inbound_links": inbound_by_project.get(current_id, []),
            "outbound_links": outbound_by_project.get(current_id, []),
        })
    status_counts: dict[str, int] = {}
    for agent in agents:
        status_counts[agent["audit_status"]] = status_counts.get(agent["audit_status"], 0) + 1
    return {
        "version": WORKBENCH_VERSION,
        "generated_at": now_iso(),
        "summary": {
            "agents": len(agents),
            "configured": status_counts.get("configured", 0),
            "observed": status_counts.get("observed", 0),
            "failed": status_counts.get("failed", 0),
            "blocked": status_counts.get("blocked", 0),
            "verified_links": sum(1 for link in link_rows if link["status"] == "verified"),
            "synthetic_links": sum(1 for link in link_rows if link["status"] == "synthetic"),
            "legacy_links": sum(1 for link in link_rows if link["status"] == "legacy"),
            "partial_links": sum(1 for link in link_rows if link["status"] == "partial"),
            "configured_links": sum(1 for link in link_rows if link["status"] == "configured"),
        },
        "agents": agents,
        "links": link_rows,
    }






def worker_instance_id() -> str:
    return WORKBENCH_INSTANCE_ID


def worker_lease(worker_id: str, *, status: str = "ready", metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    """Claim a short SQLite lease so two Workbench processes do not run one loop twice."""
    worker_id = str(worker_id).strip()
    if worker_id not in WORKER_DEFINITIONS:
        raise ValueError(f"未知 Worker：{worker_id}")
    now = datetime.now(timezone.utc)
    now_text = now.isoformat()
    lease_until = (now + timedelta(seconds=WORKER_LEASE_SECONDS)).isoformat()
    connection: sqlite3.Connection | None = None
    try:
        connection = db_connection()
        connection.execute(
            """INSERT INTO worker_leases(worker_id, instance_id, status, lease_until, last_heartbeat, metadata_json)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(worker_id) DO UPDATE SET
              instance_id = excluded.instance_id,
              status = excluded.status,
              lease_until = excluded.lease_until,
              last_heartbeat = excluded.last_heartbeat,
              metadata_json = excluded.metadata_json
            WHERE worker_leases.lease_until < ? OR worker_leases.instance_id = ?""",
            (worker_id, worker_instance_id(), status, lease_until, now_text, json.dumps(metadata or {}, ensure_ascii=False), now_text, worker_instance_id()),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM worker_leases WHERE worker_id = ?", (worker_id,)).fetchone()
        if not row or row["instance_id"] != worker_instance_id():
            return {"worker_id": worker_id, "status": "held_by_other_instance", "instance_id": row["instance_id"] if row else ""}
        result = dict(row)
        result["metadata"] = decode_json_column(result.pop("metadata_json", "{}"))
        result["lease_seconds"] = WORKER_LEASE_SECONDS
        return result
    finally:
        if connection:
            connection.close()


def release_worker_lease(worker_id: str, status: str = "stopped") -> None:
    connection = db_connection()
    try:
        connection.execute("UPDATE worker_leases SET status = ?, lease_until = '', last_heartbeat = ? WHERE worker_id = ? AND instance_id = ?", (status, now_iso(), worker_id, worker_instance_id()))
        connection.commit()
    finally:
        connection.close()


def worker_status_payload() -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        rows = {str(row["worker_id"]): dict(row) for row in connection.execute("SELECT * FROM worker_leases").fetchall()}
        runtime: dict[str, dict[str, Any]] = {}
        for worker_id in WORKER_DEFINITIONS:
            if worker_id == "crawl-worker":
                queue_row = connection.execute(
                    "SELECT COUNT(*) AS queued, SUM(CASE WHEN status = 'running' THEN 1 ELSE 0 END) AS running FROM agent_runs WHERE project_id = 'crawl4ai' AND kind = 'crawl' AND status IN ('queued', 'running')"
                ).fetchone()
                error_row = connection.execute(
                    "SELECT id AS run_id, error, updated_at FROM agent_runs WHERE project_id = 'crawl4ai' AND kind = 'crawl' AND error != '' ORDER BY updated_at DESC LIMIT 1"
                ).fetchone()
                success_row = connection.execute(
                    "SELECT id AS run_id, COALESCE(NULLIF(finished_at, ''), updated_at) AS updated_at FROM agent_runs WHERE project_id = 'crawl4ai' AND kind = 'crawl' AND status IN ('succeeded', 'completed', 'partial') AND error = '' ORDER BY COALESCE(NULLIF(finished_at, ''), updated_at) DESC LIMIT 1"
                ).fetchone()
            elif worker_id in {"sync-worker", "monitor-worker"}:
                kinds = ("market_refresh", "aihot_refresh", "sub2api_alerts") if worker_id == "sync-worker" else ("server_check",)
                placeholders = ",".join("?" for _ in kinds)
                queue_row = connection.execute(
                    f"SELECT COUNT(*) AS queued, SUM(CASE WHEN r.status = 'running' THEN 1 ELSE 0 END) AS running FROM automation_runs r JOIN automation_rules a ON a.id = r.rule_id WHERE a.kind IN ({placeholders}) AND r.status IN ('queued', 'running')",
                    kinds,
                ).fetchone()
                error_row = connection.execute(
                    f"SELECT r.id AS run_id, r.error, r.finished_at AS updated_at FROM automation_runs r JOIN automation_rules a ON a.id = r.rule_id WHERE a.kind IN ({placeholders}) AND r.error != '' ORDER BY r.finished_at DESC LIMIT 1",
                    kinds,
                ).fetchone()
                success_row = connection.execute(
                    f"SELECT r.id AS run_id, r.finished_at AS updated_at FROM automation_runs r JOIN automation_rules a ON a.id = r.rule_id WHERE a.kind IN ({placeholders}) AND r.status = 'succeeded' ORDER BY r.finished_at DESC LIMIT 1",
                    kinds,
                ).fetchone()
            else:
                queue_row = connection.execute(
                    "SELECT COUNT(*) AS queued, SUM(CASE WHEN status = 'running' THEN 1 ELSE 0 END) AS running FROM agent_runs WHERE project_id != 'crawl4ai' AND status IN ('queued', 'running')"
                ).fetchone()
                error_row = connection.execute(
                    "SELECT id AS run_id, error, updated_at FROM agent_runs WHERE project_id != 'crawl4ai' AND error != '' ORDER BY updated_at DESC LIMIT 1"
                ).fetchone()
                success_row = connection.execute(
                    "SELECT id AS run_id, COALESCE(NULLIF(finished_at, ''), updated_at) AS updated_at FROM agent_runs WHERE project_id != 'crawl4ai' AND status IN ('succeeded', 'completed', 'partial') AND error = '' ORDER BY COALESCE(NULLIF(finished_at, ''), updated_at) DESC LIMIT 1"
                ).fetchone()
            error_at = _audit_datetime(error_row["updated_at"]) if error_row else None
            success_at = _audit_datetime(success_row["updated_at"]) if success_row else None
            error_state = ""
            if error_row:
                error_state = "recovered" if success_at and (not error_at or success_at > error_at) else "recent"
            runtime[worker_id] = {
                "queue_depth": int((queue_row["queued"] if queue_row else 0) or 0),
                "running_count": int((queue_row["running"] if queue_row else 0) or 0),
                "last_error": clip(str(error_row["error"] or ""), 300) if error_row else "",
                "last_error_at": str(error_row["updated_at"] or "") if error_row else "",
                "last_run_id": str(error_row["run_id"] or "") if error_row else "",
                "last_error_state": error_state,
                "last_success_at": str(success_row["updated_at"] or "") if success_row else "",
                "last_success_run_id": str(success_row["run_id"] or "") if success_row else "",
            }
    finally:
        connection.close()
    now = datetime.now(timezone.utc)
    payload = []
    for worker_id, definition in WORKER_DEFINITIONS.items():
        row = rows.get(worker_id)
        lease_dt = _audit_datetime(row.get("lease_until")) if row else None
        heartbeat_dt = _audit_datetime(row.get("last_heartbeat")) if row else None
        claimed = bool(row and lease_dt and lease_dt > now)
        try:
            metadata = json.loads(row.get("metadata_json") or "{}") if row else {}
        except (TypeError, json.JSONDecodeError):
            metadata = {}
        payload.append({
            "id": worker_id,
            **definition,
            "status": row.get("status") if row and claimed else "unclaimed",
            "claimed": claimed,
            "instance_id": row.get("instance_id", "") if row else "",
            "last_heartbeat": row.get("last_heartbeat", "") if row else "",
            "lease_until": row.get("lease_until", "") if row else "",
            "stale": bool(row and not claimed),
            "heartbeat_age_seconds": max(0, round((now - heartbeat_dt).total_seconds())) if heartbeat_dt else None,
            "metadata": metadata if isinstance(metadata, dict) else {},
            **runtime.get(worker_id, {"queue_depth": 0, "running_count": 0, "last_error": "", "last_error_at": "", "last_run_id": "", "last_error_state": "", "last_success_at": "", "last_success_run_id": ""}),
        })
    return payload


def recover_stale_crawl_runs() -> int:
    """Put runs abandoned by a dead crawl worker back into the durable queue."""
    cutoff = datetime.now(timezone.utc) - timedelta(seconds=WORKBENCH_CRAWL_STALE_SECONDS)
    cutoff_text = cutoff.isoformat()
    now = datetime.now(timezone.utc)
    recovered: list[str] = []
    connection = db_connection()
    try:
        rows = connection.execute(
            """SELECT agent_runs.id, agent_runs.request_json,
                      worker_leases.instance_id AS lease_instance_id,
                      worker_leases.lease_until
            FROM agent_runs
            LEFT JOIN worker_leases ON worker_leases.worker_id = 'crawl-worker'
            WHERE agent_runs.project_id = 'crawl4ai' AND agent_runs.kind = 'crawl'
              AND agent_runs.status = 'running'
              AND agent_runs.started_at != '' AND agent_runs.started_at < ?""",
            (cutoff_text,),
        ).fetchall()
        for row in rows:
            run_id = str(row["id"])
            try:
                request_payload = json.loads(row["request_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                request_payload = {}
            owner_instance = str(request_payload.get("_worker_instance_id") or "") if isinstance(request_payload, dict) else ""
            lease_until = _audit_datetime(row["lease_until"]) if row["lease_until"] else None
            # A long crawl can legitimately run longer than the stale window.
            # Only recover it when the instance that claimed it no longer owns
            # the crawl-worker lease. This prevents duplicate browser work.
            owner_is_alive = bool(
                owner_instance
                and owner_instance == str(row["lease_instance_id"] or "")
                and lease_until
                and lease_until > now
            )
            if owner_is_alive:
                continue
            cursor = connection.execute(
                """UPDATE agent_runs SET status = 'queued', error = ?, started_at = '',
                   finished_at = '', updated_at = ?
                WHERE id = ? AND status = 'running'""",
                ("Crawl Worker lease 失效，已自动重新排队。", now_iso(), run_id),
            )
            if cursor.rowcount:
                recovered.append(run_id)
        connection.commit()
    finally:
        connection.close()
    for run_id in recovered:
        add_agent_run_event(run_id, "requeued", "上一 Crawl Worker 未完成，任务已恢复到队列。", level="warning")
    return len(recovered) + flag_orphaned_crawl_runs()


def flag_orphaned_crawl_runs() -> int:
    """把「没有任何 Worker 会来取」的排队任务标成失败，而不是让它永远转圈。

    原来的回收逻辑只处理 status='running' 的任务，也就是"被某个 Worker 领走后
    它死了"这一种情况。但如果 Crawl Worker 根本没启动，任务会一直停在
    'queued'：页面上显示"排队等待"，用户以为在跑，实际上永远不会有人来取，
    而且这个函数本身也只在 Crawl Worker 内部被调用——worker 不在，连回收都不会发生。

    这里改为：排队时间远超正常等待窗口、且 crawl-worker 的租约已经过期（或从来
    没有过租约）时，把任务标成失败并写明原因，让它在「最近活动」里变成一条可行动
    的线索，而不是一条沉默的假进行中。
    """
    # 给正常排队留足余量：只处理超过 stale 窗口 4 倍时间还没被领走的。
    cutoff = (datetime.now(timezone.utc) - timedelta(seconds=WORKBENCH_CRAWL_STALE_SECONDS * 4)).isoformat()
    now = datetime.now(timezone.utc)
    flagged: list[str] = []
    connection = db_connection()
    try:
        lease = connection.execute(
            "SELECT lease_until FROM worker_leases WHERE worker_id = 'crawl-worker'"
        ).fetchone()
        lease_until = _audit_datetime(lease["lease_until"]) if lease and lease["lease_until"] else None
        if lease_until and lease_until > now:
            return 0  # Worker 还活着，排队是正常的，什么都不做。
        rows = connection.execute(
            """SELECT id FROM agent_runs
            WHERE project_id = 'crawl4ai' AND kind = 'crawl' AND status = 'queued'
              AND COALESCE(NULLIF(created_at, ''), updated_at) < ?""",
            (cutoff,),
        ).fetchall()
        for row in rows:
            cursor = connection.execute(
                """UPDATE agent_runs SET status = 'failed', error = ?, finished_at = ?, updated_at = ?
                WHERE id = ? AND status = 'queued'""",
                (
                    "抓取 Worker 未运行，这个任务一直没有被领取。请检查 workbench-crawl-worker 服务后重新发起。",
                    now_iso(), now_iso(), str(row["id"]),
                ),
            )
            if cursor.rowcount:
                flagged.append(str(row["id"]))
        connection.commit()
    finally:
        connection.close()
    for run_id in flagged:
        add_agent_run_event(run_id, "orphaned", "抓取 Worker 未运行，任务长时间无人领取，已标记为失败。", level="error")
    if flagged:
        log.warning("标记了 %d 个无人领取的抓取任务（Crawl Worker 可能未运行）", len(flagged))
    return len(flagged)


def claim_next_crawl_run() -> dict[str, Any] | None:
    """Atomically claim one queued crawl run for the standalone worker."""
    connection = db_connection()
    run_id = ""
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            """SELECT id, request_json FROM agent_runs
            WHERE project_id = 'crawl4ai' AND kind = 'crawl' AND status = 'queued'
            ORDER BY created_at ASC LIMIT 1"""
        ).fetchone()
        if not row:
            connection.rollback()
            return None
        run_id = str(row["id"])
        try:
            request_payload = json.loads(row["request_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            request_payload = {}
        if not isinstance(request_payload, dict):
            request_payload = {}
        request_payload["_worker_instance_id"] = worker_instance_id()
        request_payload["_claimed_at"] = now_iso()
        cursor = connection.execute(
            """UPDATE agent_runs SET status = 'running', started_at = ?, finished_at = '',
               error = '', request_json = ?, updated_at = ?
            WHERE id = ? AND status = 'queued'""",
            (now_iso(), json.dumps(request_payload, ensure_ascii=False), now_iso(), run_id),
        )
        if cursor.rowcount != 1:
            connection.rollback()
            return None
        connection.commit()
    finally:
        connection.close()
    add_agent_run_event(run_id, "claimed", "Crawl Worker 已领取任务。", metadata={"worker": worker_instance_id()})
    return get_agent_run(run_id)


def load_market_watchlist() -> list[dict[str, str]]:
    values = load_json_file(MARKET_WATCHLIST_FILE, [])
    if not isinstance(values, list):
        return []
    return [item for item in values if isinstance(item, dict) and item.get("symbol")]


# Historical sampling is deliberately opt-in and bounded to a small, known
# set of intervals.  It reuses the existing market_refresh automation handler
# so the API-owned scheduler and the external sync worker share one execution
# path, while the source marker keeps this rule distinguishable from any
# manually-created market refresh rule.
MARKET_SAMPLING_INTERVALS: dict[int, str] = {
    300: "每 5 分钟",
    1800: "每 30 分钟",
    3600: "每 1 小时",
    86400: "每天",
}
MARKET_SAMPLING_SOURCE = "market_sampling"
MARKET_SAMPLING_RULE_NAME = "量化历史样本采集"


def market_sampling_rule() -> dict[str, Any] | None:
    """Return the one rule owned by the explicit market sampling control."""
    candidates = []
    for rule in automation_rules():
        config = rule.get("config") if isinstance(rule.get("config"), dict) else {}
        if (
            str(rule.get("kind") or "") == "market_refresh"
            and str(rule.get("project_id") or "") == "market"
            and str(config.get("source") or "") == MARKET_SAMPLING_SOURCE
        ):
            candidates.append(rule)
    return max(candidates, key=lambda item: int(item.get("id") or 0), default=None)


def market_history_count() -> int:
    """Read the full persisted sample count without the UI's display limit."""
    connection = db_connection()
    try:
        row = connection.execute("SELECT COUNT(*) AS count FROM market_snapshots").fetchone()
        return int(row["count"] or 0) if row else 0
    finally:
        connection.close()


def load_market_snapshot() -> dict[str, Any]:
    values = load_json_file(MARKET_SNAPSHOT_FILE, {})
    if not isinstance(values, dict):
        values = {}
    # The editable watchlist is the source of truth.  A quote snapshot may be
    # older than the latest edit, so never let removed symbols leak back into
    # today's cards, AI summaries, or portfolio counts.
    watchlist = load_market_watchlist()
    allowed_symbols = {
        normalize_market_symbol(str(item.get("symbol") or ""))
        for item in watchlist
        if isinstance(item, dict)
    }
    allowed_symbols.discard("")
    quotes = [
        item for item in (values.get("quotes") or [])
        if isinstance(item, dict)
        and normalize_market_symbol(str(item.get("symbol") or "")) in allowed_symbols
    ]
    values["watchlist"] = watchlist
    values["quotes"] = quotes
    if not watchlist:
        values.update({"checked_at": "", "status": "empty", "missing_symbols": []})
    return values


