def parse_aihot_items(html: str) -> list[dict[str, Any]]:
    """Read the public SSR data from aiHot's Next.js page.

    We intentionally consume only the public initialNewsData payload. This
    avoids copying the site's UI and keeps the workbench's wrapper focused on
    filtering, provenance and Agent conversation.
    """
    pattern = r'self\.__next_f\.push\(\[1,"((?:\\.|[^"\\])*)"\]\)'
    chunks = []
    for match in re.finditer(pattern, html):
        try:
            chunks.append(json.loads('"' + match.group(1) + '"'))
        except json.JSONDecodeError:
            continue
    payload = "\n".join(chunks)
    marker = '"initialNewsData":'
    start = payload.find(marker)
    if start < 0:
        return []
    start += len(marker)
    try:
        parsed, _ = json.JSONDecoder().raw_decode(payload[start:].lstrip())
    except json.JSONDecodeError:
        return []
    if not isinstance(parsed, list):
        return []
    items = []
    for raw in parsed:
        if not isinstance(raw, dict) or not raw.get("id"):
            continue
        published_at = str(raw.get("published_at") or "").removeprefix("$D")
        tags = [tag.strip() for tag in str(raw.get("tag") or "").split(",") if tag.strip()]
        items.append(
            {
                "id": str(raw.get("id")),
                "title": raw.get("title_trans") or raw.get("title") or "未命名资讯",
                "description": raw.get("des_trans") or raw.get("des") or "",
                "source": raw.get("sources") or "未知来源",
                "tags": tags,
                "published_at": published_at,
                "link": raw.get("link") or "",
                "importance": int(raw.get("importance") or 0),
                "business_opportunity": raw.get("business_opportunity") or "",
                "layer": raw.get("layer") or "",
                "value": raw.get("value") or "",
                "impact": raw.get("impact") or "",
            }
        )
    return dedupe_aihot_items(items)


def normalized_aihot_title(title: str) -> str:
    """Make translated/source title variants comparable for feed de-duplication."""
    normalized = unicodedata.normalize("NFKC", str(title or "")).lower()
    return re.sub(r"[^0-9a-z\u4e00-\u9fff]+", "", normalized)


def canonical_aihot_link(link: str) -> str:
    value = str(link or "").strip()
    if not value:
        return ""
    parsed = urlparse(value)
    if not parsed.netloc:
        return value.lower().rstrip("/")
    return f"{parsed.netloc.lower()}{parsed.path.rstrip('/').lower()}"


def parse_rss_items(xml_text: str, source_name: str) -> list[dict[str, Any]]:
    """Parse RSS 2.0 / Atom feeds into the same shape as `parse_aihot_items`.

    Uses only the standard library so the workbench has no extra install cost.
    Stories without a title or link are dropped; importance / business_opportunity
    default to 0 / "" so the dedupe pass keeps the richer record when the same
    story shows up on multiple sources.
    """
    from xml.etree import ElementTree as ET
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return []
    items: list[dict[str, Any]] = []
    hash_inputs: list[str] = []
    for entry in root.iter("item"):
        title = (entry.findtext("title") or "").strip()
        link = (entry.findtext("link") or "").strip()
        desc = (entry.findtext("description") or "").strip()
        pub = (entry.findtext("pubDate") or "").strip()
        if not title or not link:
            continue
        hash_inputs.append(link)
        items.append({
            "id": f"rss:{hashlib.md5(link.encode('utf-8')).hexdigest()[:12]}",
            "title": title,
            "description": _strip_html(desc)[:300],
            "source": source_name,
            "tags": [],
            "published_at": pub,
            "link": link,
            "importance": 0,
            "business_opportunity": "",
            "layer": "",
        })
    if not items:
        ns = {"atom": "http://www.w3.org/2005/Atom"}
        for entry in root.findall("atom:entry", ns):
            title = (entry.findtext("atom:title", default="", namespaces=ns) or "").strip()
            link_el = entry.find("atom:link", ns)
            link = link_el.get("href", "") if link_el is not None else ""
            desc = (entry.findtext("atom:summary", default="", namespaces=ns) or entry.findtext("atom:content", default="", namespaces=ns) or "").strip()
            pub = (entry.findtext("atom:updated", default="", namespaces=ns) or entry.findtext("atom:published", default="", namespaces=ns) or "").strip()
            if not title or not link:
                continue
            items.append({
                "id": f"rss:{hashlib.md5(link.encode('utf-8')).hexdigest()[:12]}",
                "title": title,
                "description": _strip_html(desc)[:300],
                "source": source_name,
                "tags": [],
                "published_at": pub,
                "link": link,
                "importance": 0,
                "business_opportunity": "",
                "layer": "",
            })
    return items


def _strip_html(value: str) -> str:
    from html.parser import HTMLParser as _HTMLParser
    class _Stripper(_HTMLParser):
        def __init__(self):
            super().__init__()
            self._buf: list[str] = []
        def handle_data(self, data):
            self._buf.append(data)
    if not value:
        return ""
    parser = _Stripper()
    try:
        parser.feed(value)
    except Exception:
        return value
    return " ".join("".join(parser._buf).split())


def dedupe_aihot_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse repeated stories from multiple sources while keeping the best record."""
    result: list[dict[str, Any]] = []
    key_to_index: dict[str, int] = {}
    for item in items:
        keys = []
        link_key = canonical_aihot_link(item.get("link", ""))
        title_key = normalized_aihot_title(item.get("title", ""))
        if link_key:
            keys.append(f"link:{link_key}")
        if title_key:
            keys.append(f"title:{title_key}")
        existing_index = next((key_to_index[key] for key in keys if key in key_to_index), None)
        if existing_index is None:
            existing_index = len(result)
            result.append(item)
        else:
            current = result[existing_index]
            current_score = (
                int(current.get("importance") or 0),
                bool(current.get("business_opportunity")),
                len(str(current.get("description") or "")),
                str(current.get("published_at") or ""),
            )
            item_score = (
                int(item.get("importance") or 0),
                bool(item.get("business_opportunity")),
                len(str(item.get("description") or "")),
                str(item.get("published_at") or ""),
            )
            if item_score > current_score:
                result[existing_index] = item
        for key in keys:
            key_to_index[key] = existing_index
    return result


def list_aihot_feedback(item_ids: list[str] | None = None) -> dict[str, dict[str, Any]]:
    """Read local-only feedback used to personalize the signal list."""
    connection = db_connection()
    try:
        if item_ids:
            normalized = [str(item_id) for item_id in item_ids if str(item_id).strip()]
            if not normalized:
                return {}
            placeholders = ",".join("?" for _ in normalized)
            rows = connection.execute(
                f"SELECT * FROM aihot_feedback WHERE item_id IN ({placeholders})", normalized
            ).fetchall()
        else:
            rows = connection.execute("SELECT * FROM aihot_feedback").fetchall()
        return {
            str(row["item_id"]): {
                "item_id": str(row["item_id"]),
                "vote": row["vote"],
                "note": row["note"],
                "created_at": row["created_at"],
                "updated_at": row["updated_at"],
            }
            for row in rows
        }
    finally:
        connection.close()


def save_aihot_feedback(item_id: str, vote: str, note: str = "") -> dict[str, Any]:
    timestamp = now_iso()
    connection: sqlite3.Connection | None = None
    try:
        connection = db_connection()
        connection.execute(
            """INSERT INTO aihot_feedback (item_id, vote, note, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(item_id) DO UPDATE SET vote = excluded.vote, note = excluded.note, updated_at = excluded.updated_at""",
            (str(item_id), vote, clip(note.strip(), 1_000), timestamp, timestamp),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM aihot_feedback WHERE item_id = ?", (str(item_id),)).fetchone()
        return {
            "item_id": str(row["item_id"]),
            "vote": row["vote"],
            "note": row["note"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        }
    finally:
        connection.close()


def cid_snapshot_row(row: sqlite3.Row) -> dict[str, Any]:
    snapshot = decode_json_column(row["snapshot_json"])
    return {
        "id": row["id"],
        "repo": row["repo"],
        "source_url": row["source_url"],
        "fetched_at": row["fetched_at"],
        "project_count": row["project_count"],
        "snapshot": snapshot,
        "created_at": row["created_at"],
    }


def refresh_cid_opportunity_status(repo: str, projects: list[dict[str, Any]], fetched_at: str) -> int:
    """登记过的机会卡项目在新快照里状态/描述有变化时，刷新卡片并通知。

    只更新已登记机会（opportunity work_item + artifact），不自动创建新机会。
    返回更新的机会卡数量；没有变化或没有登记时返回 0。
    """
    if not projects:
        return 0
    by_key = {str(item.get("key") or ""): item for item in projects if item.get("key")}
    if not by_key:
        return 0
    updated = 0
    for item in list_work_items("all", "cid-dashboard"):
        meta = item.get("metadata") or {}
        opportunity_key = str(meta.get("opportunity_key") or "")
        if not opportunity_key or not opportunity_key.startswith("cid:"):
            continue
        project_key = str(meta.get("project_key") or "")
        current = by_key.get(project_key)
        if not current:
            continue
        status = str(current.get("status") or "")
        name = str(current.get("name") or "")
        desc = clip(str(current.get("desc") or ""), 1_000)
        signal = meta.get("signal") if isinstance(meta.get("signal"), dict) else {}
        old_status = str(signal.get("status") or meta.get("project_status") or "")
        old_name = str(signal.get("name") or meta.get("project_name") or "")
        if status == old_status and name == old_name:
            continue
        new_signal = {**signal, "status": status, "name": name, "status_changed_from": old_status or "未知", "last_refreshed_at": now_iso()}
        new_meta = {**meta, "signal": new_signal, "project_status": status, "project_name": name, "last_refreshed_at": now_iso(), "status_changed_from": old_status or "未知"}
        update_work_item_record(
            item["id"],
            {
                "description": clip(f"看板项目 {name} 状态更新为 {status or '未知'}（{fetched_at}）。原描述：{desc or '无'}", 1_500),
                "metadata": new_meta,
            },
        )
        try:
            create_notification_record(
                title=f"看板机会更新：{name}",
                body=f"登记过的看板项目状态变化：{old_status or '未知'} → {status or '未知'}（数据时间 {fetched_at}）。",
                project_id="cid-dashboard",
                kind="agent_action",
                level="info",
                href="/projects/cid-dashboard",
                event_key=f"cid-opportunity-update:{item['id']}:{fetched_at}",
                dedupe_seconds=0,
            )
        except Exception:  # noqa: BLE001
            log.debug("忽略异常（refresh_cid_opportunity_status）", exc_info=True)
        updated += 1
    return updated


def save_cid_dashboard_snapshot(payload: dict[str, Any]) -> dict[str, Any]:
    """Persist a bounded, non-sensitive snapshot from the CID dashboard."""
    repo = clip(str(payload.get("repo") or ""), 180).strip()
    if not repo or "/" not in repo:
        raise ValueError("看板数据源必须是 owner/repo")
    source_url = clip(str(payload.get("source_url") or ""), 1_000).strip()
    fetched_at = clip(str(payload.get("fetched_at") or now_iso()), 80).strip()
    raw = payload.get("snapshot") if isinstance(payload.get("snapshot"), dict) else {}
    def safe_count(value: Any) -> int:
        try:
            return max(0, min(int(value or 0), 100_000))
        except (TypeError, ValueError):
            return 0

    raw_status_counts = raw.get("status_counts") if isinstance(raw.get("status_counts"), dict) else {}
    raw_top_tags = raw.get("top_tags") if isinstance(raw.get("top_tags"), list) else []
    snapshot = {
        "status_counts": {clip(str(key), 80): safe_count(value) for key, value in list(raw_status_counts.items())[:20]},
        "top_tags": [[clip(str(pair[0]), 80), safe_count(pair[1])] for pair in raw_top_tags[:20] if isinstance(pair, (list, tuple)) and len(pair) >= 2],
        "projects": [],
    }
    projects = raw.get("projects") if isinstance(raw.get("projects"), list) else []
    safe_projects = []
    for project in projects[:160]:
        if not isinstance(project, dict):
            continue
        safe_projects.append(
            {
                "key": clip(str(project.get("key") or ""), 240),
                "name": clip(str(project.get("name") or ""), 240),
                "url": clip(str(project.get("url") or ""), 1_000),
                "desc": clip(str(project.get("desc") or ""), 1_000),
                "dev": clip(str(project.get("dev") or ""), 160),
                "status": clip(str(project.get("status") or ""), 40),
                "tags": [clip(str(tag), 80) for tag in (project.get("tags") or [])[:8]],
                "group": clip(str(project.get("group") or project.get("groupLabel") or ""), 160),
            }
        )
    snapshot["projects"] = safe_projects
    snapshot["project_count"] = max(0, min(int(payload.get("project_count") or len(safe_projects)), 100_000))
    snapshot_json = json.dumps(snapshot, ensure_ascii=False, sort_keys=True)
    connection = db_connection()
    try:
        previous = connection.execute(
            "SELECT * FROM cid_dashboard_snapshots WHERE repo = ? ORDER BY id DESC LIMIT 1", (repo,)
        ).fetchone()
        if previous:
            previous_snapshot = decode_json_column(previous["snapshot_json"])
            previous_snapshot.pop("saved_at", None)
            if previous["source_url"] == source_url and previous_snapshot == snapshot:
                return cid_snapshot_row(previous)
        cursor = connection.execute(
            """INSERT INTO cid_dashboard_snapshots
            (repo, source_url, fetched_at, project_count, snapshot_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?)""",
            (repo, source_url, fetched_at, snapshot["project_count"], snapshot_json, now_iso()),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM cid_dashboard_snapshots WHERE id = ?", (cursor.lastrowid,)).fetchone()
        saved = cid_snapshot_row(row)
    finally:
        connection.close()

    # 机会卡状态自动刷新：已登记的机会项目在新快照里状态/描述有变化时，
    # 更新机会卡描述并登记一条通知，让登记过的机会保持最新。
    try:
        refresh_cid_opportunity_status(repo, safe_projects, fetched_at)
    except Exception:  # noqa: BLE001
        log.debug("忽略异常（save_cid_dashboard_snapshot）", exc_info=True)
    return saved


def list_cid_dashboard_snapshots(repo: str = "", limit: int = 20) -> list[dict[str, Any]]:
    connection = db_connection()
    try:
        if repo:
            rows = connection.execute(
                "SELECT * FROM cid_dashboard_snapshots WHERE repo = ? ORDER BY created_at DESC LIMIT ?",
                (repo, max(1, min(limit, 50))),
            ).fetchall()
        else:
            rows = connection.execute(
                "SELECT * FROM cid_dashboard_snapshots ORDER BY created_at DESC LIMIT ?",
                (max(1, min(limit, 50)),),
            ).fetchall()
        return [cid_snapshot_row(row) for row in rows]
    finally:
        connection.close()


def cid_opportunity_for_project(opportunity_key: str) -> dict[str, Any] | None:
    for work_item in list_work_items("all", "cid-dashboard"):
        metadata = work_item.get("metadata") if isinstance(work_item.get("metadata"), dict) else {}
        if metadata.get("opportunity_key") == opportunity_key:
            return work_item
    return None


def aihot_opportunity_for_item(item_id: str) -> dict[str, Any] | None:
    key = f"aihot:{str(item_id)}"
    for work_item in list_work_items("all", "aihot"):
        metadata = work_item.get("metadata") if isinstance(work_item.get("metadata"), dict) else {}
        if metadata.get("opportunity_key") == key:
            return work_item
    return None


def enrich_aihot_items(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    feedback = list_aihot_feedback([str(item.get("id")) for item in items])
    opportunities = {
        str(item.get("metadata", {}).get("opportunity_key")): item
        for item in list_work_items("all", "aihot")
        if isinstance(item.get("metadata"), dict) and item.get("metadata", {}).get("opportunity_key")
    }
    enriched = []
    for raw_item in items:
        item = dict(raw_item)
        item_feedback = feedback.get(str(item.get("id")))
        opportunity = opportunities.get(f"aihot:{item.get('id')}")
        item["feedback"] = item_feedback or {"item_id": str(item.get("id")), "vote": "", "note": ""}
        item["opportunity_work_item_id"] = opportunity.get("id") if opportunity else None
        item["opportunity_status"] = opportunity.get("status") if opportunity else ""
        item["opportunity_score"] = opportunity_score(item, item["feedback"])
        enriched.append(item)
    return enriched


async def fetch_aihot_snapshot(*, force: bool = False) -> dict[str, Any]:
    current = load_aihot_snapshot()
    fetched_at = current.get("fetched_at")
    fresh = False
    if fetched_at and not force:
        try:
            fresh = (datetime.now(timezone.utc) - datetime.fromisoformat(fetched_at)).total_seconds() < 1800
        except ValueError:
            fresh = False
    if fresh and current.get("items"):
        return current
    async def fetch_one(client: httpx.AsyncClient, url: str) -> tuple[str, list[dict[str, Any]]]:
        try:
            response = await client.get(url, headers={"User-Agent": "Workbench/0.2"})
            response.raise_for_status()
            body = response.text
        except Exception as exc:
            return (url, [{"_error": str(exc)}])
        if "aihot.today" in url:
            batch = parse_aihot_items(body)
            for entry in batch:
                entry["domain"] = "ai"
            return (url, batch)
        host = _hostname(url)
        batch = parse_rss_items(body, host)
        domain = _aihot_domain(host)
        for entry in batch:
            entry["domain"] = domain
        return (url, batch)
    try:
        async with httpx.AsyncClient(timeout=10, trust_env=False, headers={"User-Agent": "Workbench/0.2"}) as client:
            results = await asyncio.gather(*(fetch_one(client, url) for url in AIHOT_SOURCES), return_exceptions=False)
        items: list[dict[str, Any]] = []
        errors: list[str] = []
        for _url, batch in results:
            for entry in batch:
                if "_error" in entry:
                    errors.append(str(entry["_error"]))
                elif _aihot_relevant(entry):
                    items.append(entry)
        if not items:
            raise RuntimeError(f"AI 热点多源均未读到数据 ({'; '.join(errors)[:200]})")
        snapshot = {
            "source": " + ".join(_hostname(url) for url in AIHOT_SOURCES),
            "source_url": AIHOT_SOURCES[0],
            "sources": list(AIHOT_SOURCES),
            "fetched_at": now_iso(),
            "items": items,
            "previous_items": [
                {"id": item.get("id"), "title": item.get("title"), "link": item.get("link"), "published_at": item.get("published_at")}
                for item in dedupe_aihot_items(list(current.get("items") or []))[:200]
                if isinstance(item, dict)
            ],
            "stale": False,
            "error": " | ".join(errors)[:500] if errors else "",
        }
        save_aihot_snapshot(snapshot)
        register_artifact_safely(
            project_id="aihot",
            name="aihot_snapshot.json",
            path=str(AIHOT_SNAPSHOT_FILE),
            kind="aihot_feed",
            metadata={"item_count": len(items), "source_count": len(AIHOT_SOURCES)},
        )
        return snapshot
    except Exception as exc:
        if current.get("items"):
            current["stale"] = True
            current["error"] = str(exc)
            return current
        raise HTTPException(502, f"AI 热点同步失败：{exc}") from exc


def _hostname(url: str) -> str:
    from urllib.parse import urlparse as _urlparse
    try:
        return _urlparse(url).netloc or url
    except ValueError:
        return url


def select_aihot_items(snapshot: dict[str, Any], mode: str = "useful", query: str = "", limit: int = 40, domain: str = "") -> list[dict[str, Any]]:
    items = dedupe_aihot_items(list(snapshot.get("items") or []))
    query = query.strip().lower()
    if query:
        items = [item for item in items if query in json.dumps(item, ensure_ascii=False).lower()]
    if domain and domain != "all":
        items = [item for item in items if (item.get("domain") or "综合") == domain]
    feedback = list_aihot_feedback([str(item.get("id")) for item in items])
    # 变化检测：对比上一次快照（previous_items），标记新出现的热点
    previous = snapshot.get("previous_items") or []
    previous_ids = {str(item.get("id")) for item in previous if isinstance(item, dict)}
    previous_titles = {normalized_aihot_title(str(item.get("title") or "")) for item in previous if isinstance(item, dict)}

    def change_label(item: dict[str, Any]) -> str:
        if str(item.get("id") or "") in previous_ids:
            return ""
        return "" if normalized_aihot_title(str(item.get("title") or "")) in previous_titles else "new"

    # 来源质量评分：基于该来源下所有条目的用户反馈。
    # 细化：同时统计有用/不相关样本量，按“有用率 + 样本量”加权，
    # 有足够样本的来源分数更可信，样本少时向基准 3 分收缩。
    source_votes: dict[str, int] = {}
    source_used: dict[str, int] = {}
    source_total: dict[str, int] = {}
    for item in items:
        src = str(item.get("source") or "未知来源")
        vote = str(feedback.get(str(item.get("id")), {}).get("vote", ""))
        if vote == "useful":
            source_votes[src] = source_votes.get(src, 0) + 1
            source_used[src] = source_used.get(src, 0) + 1
            source_total[src] = source_total.get(src, 0) + 1
        elif vote == "not_useful":
            source_votes[src] = source_votes.get(src, 0) - 1
            source_total[src] = source_total.get(src, 0) + 1
    for index, raw_item in enumerate(items):
        updated = dict(raw_item)
        updated["change"] = change_label(updated)
        src = str(updated.get("source") or "未知来源")
        votes = source_votes.get(src, 0)
        total = source_total.get(src, 0)
        # 有用率加权：样本越多，越向“有用率”靠；样本少时回到基准 3 分。
        if total >= 5:
            usefulness = source_used.get(src, 0) / total
            score = 1 + usefulness * 4
        elif total >= 2:
            usefulness = source_used.get(src, 0) / total
            score = 3 + (usefulness - 0.5) * 2
        else:
            score = 3 + votes
        updated["source_score"] = max(0, min(5, round(score, 2)))
        updated["source_votes"] = votes
        updated["source_sample_size"] = total
        items[index] = updated

    def preference_score(item: dict[str, Any]) -> int:
        vote = str(feedback.get(str(item.get("id")), {}).get("vote", ""))
        return 5 if vote == "useful" else -8 if vote == "not_useful" else 0

    def ranked_key(item: dict[str, Any]) -> tuple[int, int, str]:
        return (int(item.get("importance") or 0) + preference_score(item) + item.get("source_score", 3) - 3, 1 if item.get("change") == "new" else 0, str(item.get("published_at") or ""))

    if mode == "useful":
        items.sort(key=ranked_key, reverse=True)
    elif mode == "opportunity":
        opportunity_items = [item for item in items if item.get("business_opportunity") or any(tag in {"Product", "Company", "Industry", "Agent"} for tag in item.get("tags", []))]
        items = opportunity_items or items
        items.sort(key=ranked_key, reverse=True)
    else:
        items.sort(key=lambda item: item.get("published_at", ""), reverse=True)
    return enrich_aihot_items(items[: max(1, min(limit, 100))])




def github_repository_parts(values: dict[str, str]) -> tuple[str, str]:
    """Validate the repository path before putting user input into a URL."""
    owner = str(values.get("owner") or "").strip()
    repo = str(values.get("repo") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", owner) or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", repo):
        raise HTTPException(400, "GitHub：用户名/组织和仓库名只能包含字母、数字、点、下划线或短横线")
    return owner, repo


def _plain_external_text(value: Any, limit: int = 500) -> str:
    text = re.sub(r"<[^>]+>", " ", str(value or ""))
    text = re.sub(r"\s+", " ", text).strip()
    return clip(text, limit)


def _activitywatch_buckets(payload: Any) -> list[dict[str, Any]]:
    """Normalize ActivityWatch's map/list bucket responses without retaining raw events."""
    candidates: list[dict[str, Any]] = []
    if isinstance(payload, dict):
        for key, value in payload.items():
            if not isinstance(value, dict):
                continue
            bucket = dict(value)
            bucket.setdefault("id", key)
            candidates.append(bucket)
    elif isinstance(payload, list):
        candidates = [dict(value) for value in payload if isinstance(value, dict)]
    normalized = []
    for bucket in candidates:
        bucket_id = str(bucket.get("id") or "").strip()
        if not bucket_id:
            continue
        normalized.append({
            "id": bucket_id,
            "name": str(bucket.get("name") or bucket.get("type") or bucket_id).strip()[:160],
            "type": str(bucket.get("type") or "").strip()[:80],
            "client": str(bucket.get("client") or "").strip()[:80],
        })
    return normalized


def _activitywatch_events(payload: Any) -> list[dict[str, Any]]:
    if isinstance(payload, list):
        return [event for event in payload if isinstance(event, dict)]
    if isinstance(payload, dict) and isinstance(payload.get("events"), list):
        return [event for event in payload["events"] if isinstance(event, dict)]
    return []


def _activitywatch_duration(events: list[dict[str, Any]]) -> float:
    total = 0.0
    for event in events:
        try:
            duration = float(event.get("duration") or 0)
        except (TypeError, ValueError):
            duration = 0.0
        if math.isfinite(duration) and duration > 0:
            total += duration
    return round(total, 3)


def bind_feishu_chat(chat_id: str, user_open_id: str = "", user_name: str = "") -> None:
    if not chat_id:
        return
    connection = db_connection()
    try:
        connection.execute(
            """INSERT INTO feishu_bindings (chat_id, user_open_id, user_name, bound_at, last_active_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(chat_id) DO UPDATE SET user_open_id = excluded.user_open_id, user_name = excluded.user_name, last_active_at = excluded.last_active_at""",
            (chat_id, user_open_id, user_name, now_iso(), now_iso()),
        )
        connection.commit()
    finally:
        connection.close()


def claim_feishu_event(payload: dict[str, Any], *, retention_days: int = 7) -> bool:
    """Atomically claim one Feishu event and suppress provider retries.

    Feishu retries callbacks when the first response is slow or unavailable.
    Without a receipt, a single ``云开发 ... 运行测试`` message could enqueue
    the same test more than once. Events without a provider id are allowed
    through because there is no safe stable key to deduplicate.
    """
    event_key = feishu_bot.event_receipt_key(payload)
    if not event_key:
        return True
    received_at = now_iso()
    cutoff = (datetime.now(timezone.utc) - timedelta(days=max(1, retention_days))).isoformat()
    header = payload.get("header") if isinstance(payload.get("header"), dict) else {}
    event_type = str(header.get("event_type") or payload.get("type") or "")[:120]
    connection = db_connection()
    try:
        connection.execute("DELETE FROM feishu_event_receipts WHERE received_at < ?", (cutoff,))
        cursor = connection.execute(
            "INSERT OR IGNORE INTO feishu_event_receipts (event_key, event_type, received_at) VALUES (?, ?, ?)",
            (event_key, event_type, received_at),
        )
        connection.commit()
        return cursor.rowcount == 1
    finally:
        connection.close()


def save_market_watchlist(values: list[dict[str, str]]) -> None:
    save_json_atomic(MARKET_WATCHLIST_FILE, values, 0o600)


def save_market_snapshot(values: dict[str, Any]) -> None:
    save_json_atomic(MARKET_SNAPSHOT_FILE, values, 0o600)


def market_snapshot_row(row: sqlite3.Row) -> dict[str, Any]:
    def decode_list(value: str) -> list[Any]:
        try:
            parsed = json.loads(value or "[]")
        except json.JSONDecodeError:
            return []
        return parsed if isinstance(parsed, list) else []

    return {
        "id": row["id"],
        "checked_at": row["checked_at"],
        "source": row["source"],
        "status": row["status"],
        "watchlist": decode_list(row["watchlist_json"]),
        "quotes": decode_list(row["quotes_json"]),
        "created_at": row["created_at"],
    }


def market_timestamp_key(value: Any) -> str:
    """Return a stable UTC key for equivalent ISO timestamps.

    Providers may spell the same instant with ``Z`` or an explicit offset.
    Keeping the display value while using a canonical key prevents duplicate
    research points from entering the history series.
    """
    parsed = _sub2api_timestamp(value)
    return parsed.isoformat() if parsed else str(value or "").strip()


def record_market_snapshot(snapshot: dict[str, Any]) -> dict[str, Any] | None:
    """Persist only usable quote history without changing the JSON snapshot contract."""
    checked_at = str(snapshot.get("checked_at") or "").strip()
    if not checked_at:
        return None
    watchlist = [item for item in snapshot.get("watchlist", []) if isinstance(item, dict) and item.get("symbol")]
    quotes = [item for item in snapshot.get("quotes", []) if isinstance(item, dict) and item.get("symbol")]
    # A failed/empty provider response is still kept in market_snapshot.json
    # for troubleshooting, but it must not become a usable research point.
    usable_quotes = [quote for quote in quotes if market_quote_quality(quote).get("valid")]
    if not usable_quotes:
        return None
    connection = db_connection()
    try:
        existing = connection.execute(
            "SELECT * FROM market_snapshots WHERE checked_at = ? ORDER BY id DESC LIMIT 1",
            (checked_at,),
        ).fetchone()
        if not existing:
            # Fall back to a bounded canonical-time lookup for providers that
            # changed from ``Z`` to ``+00:00`` (or vice versa).
            candidates = connection.execute("SELECT * FROM market_snapshots ORDER BY id DESC LIMIT 500").fetchall()
            incoming_key = market_timestamp_key(checked_at)
            existing = next((row for row in candidates if market_timestamp_key(row["checked_at"]) == incoming_key), None)
        if existing:
            existing_payload = market_snapshot_row(existing)
            existing_quotes = {
                normalize_market_symbol(item.get("symbol", "")): item
                for item in existing_payload.get("quotes", [])
                if isinstance(item, dict) and normalize_market_symbol(item.get("symbol", ""))
            }
            for quote in usable_quotes:
                existing_quotes[normalize_market_symbol(quote.get("symbol", ""))] = quote
            merged_quotes = list(existing_quotes.values())
            existing_watchlist = {
                normalize_market_symbol(item.get("symbol", "")): item
                for item in existing_payload.get("watchlist", [])
                if isinstance(item, dict) and normalize_market_symbol(item.get("symbol", ""))
            }
            for item in watchlist:
                existing_watchlist[normalize_market_symbol(item.get("symbol", ""))] = item
            sources = {
                str(existing_payload.get("source") or "unknown"),
                str(snapshot.get("source") or "unknown"),
            }
            sources.discard("unknown")
            source = next(iter(sources)) if len(sources) == 1 else "mixed" if sources else "unknown"
            connection.execute(
                "UPDATE market_snapshots SET source = ?, status = ?, watchlist_json = ?, quotes_json = ? WHERE id = ?",
                (
                    source,
                    "ok" if merged_quotes else str(snapshot.get("status") or existing_payload.get("status") or "ok"),
                    json.dumps(list(existing_watchlist.values()), ensure_ascii=False),
                    json.dumps(merged_quotes, ensure_ascii=False),
                    existing["id"],
                ),
            )
            connection.commit()
            row = connection.execute("SELECT * FROM market_snapshots WHERE id = ?", (existing["id"],)).fetchone()
            return market_snapshot_row(row) if row else existing_payload
        cursor = connection.execute(
            """INSERT INTO market_snapshots
            (checked_at, source, status, watchlist_json, quotes_json, created_at)
            VALUES (?, ?, ?, ?, ?, ?)""",
            (
                checked_at,
                str(snapshot.get("source") or "unknown"),
                str(snapshot.get("status") or "ok"),
                json.dumps(watchlist, ensure_ascii=False),
                json.dumps(usable_quotes, ensure_ascii=False),
                now_iso(),
            ),
        )
        connection.commit()
        row = connection.execute("SELECT * FROM market_snapshots WHERE id = ?", (cursor.lastrowid,)).fetchone()
        return market_snapshot_row(row) if row else None
    finally:
        connection.close()


def list_market_history(limit: int = 30) -> list[dict[str, Any]]:
    requested = max(1, min(limit, 100))
    connection = db_connection()
    try:
        # checked_at can contain equivalent instants with different offsets
        # (for example ``Z`` and ``+08:00``).  SQL text ordering is not
        # chronological across offsets, so fetch a bounded recent window and
        # sort the decoded rows by the canonical UTC timestamp below.
        rows = connection.execute(
            "SELECT * FROM market_snapshots ORDER BY id DESC LIMIT ?",
            (max(requested, 5000),),
        ).fetchall()
        items = [market_snapshot_row(row) for row in rows]
        items.sort(
            key=lambda item: (
                _sub2api_timestamp(item.get("checked_at")) or datetime.min.replace(tzinfo=timezone.utc),
                int(item.get("id") or 0),
            ),
            reverse=True,
        )
        return items[:requested]
    finally:
        connection.close()


def market_sampling_state() -> dict[str, Any]:
    """Build a truthful status payload for the opt-in sampling control."""
    rule = market_sampling_rule()
    config = rule.get("config") if isinstance(rule and rule.get("config"), dict) else {}
    schedule = str(rule.get("schedule") or "") if rule else ""
    schedule_match = re.fullmatch(r"every:(\d+)", schedule)
    interval_seconds = int(schedule_match.group(1)) if schedule_match else int(config.get("interval_seconds") or 1800)
    if interval_seconds not in MARKET_SAMPLING_INTERVALS:
        interval_seconds = 1800

    history = list_market_history(limit=1)
    latest = history[0] if history else None
    history_count = market_history_count()
    rule_id = int(rule.get("id") or 0) if rule else 0
    runs = list_automation_runs(rule_id, limit=5) if rule_id else []
    latest_run = runs[0] if runs else None
    last_error = str((rule or {}).get("last_error") or "").strip()
    if latest_run and latest_run.get("status") == "failed":
        last_error = str(latest_run.get("error") or last_error).strip()

    last_run_at = str((rule or {}).get("last_run_at") or "").strip()
    next_run_at = ""
    last_dt = _sub2api_timestamp(last_run_at) if last_run_at else None
    if rule and rule.get("enabled") and last_dt:
        next_run_at = (last_dt + timedelta(seconds=interval_seconds)).isoformat()

    latest_run_summary = None
    if latest_run:
        latest_run_summary = {
            "id": latest_run.get("id"),
            "status": latest_run.get("status"),
            "trigger": latest_run.get("trigger"),
            "created_at": latest_run.get("created_at"),
            "started_at": latest_run.get("started_at"),
            "finished_at": latest_run.get("finished_at"),
            "error": latest_run.get("error") or "",
        }

    latest_snapshot = None
    if latest:
        latest_snapshot = {
            "checked_at": latest.get("checked_at") or "",
            "source": latest.get("source") or "",
            "status": latest.get("status") or "",
            "quote_count": len(latest.get("quotes") or []),
        }

    enabled = bool(rule and rule.get("enabled"))
    return {
        "enabled": enabled,
        "status": "enabled" if enabled else "disabled",
        "interval_seconds": interval_seconds,
        "interval_label": MARKET_SAMPLING_INTERVALS[interval_seconds],
        "allowed_intervals": [
            {"seconds": seconds, "label": label}
            for seconds, label in MARKET_SAMPLING_INTERVALS.items()
        ],
        "watchlist_count": len(load_market_watchlist()),
        "history_count": history_count,
        "latest_snapshot": latest_snapshot,
        "last_run_at": last_run_at,
        "next_run_at": next_run_at,
        "last_run": latest_run_summary,
        "failure_reason": last_error,
        "rule_id": rule_id or None,
        "policy": "仅在用户明确开启后按固定周期读取公开行情并保存本地历史快照；关闭后保留历史，不连接券商、不自动下单。",
    }


def market_quote_quality(quote: dict[str, Any]) -> dict[str, Any]:
    price = parse_market_number(quote.get("price"))
    previous = parse_market_number(quote.get("previous_close"))
    provided_change = parse_market_number(quote.get("change_pct"))
    reasons: list[str] = []
    if price is None or price <= 0:
        reasons.append("现价缺失或无效")
    if previous is None or previous <= 0:
        reasons.append("昨收缺失或无效")
    calculated_change = None
    if price is not None and previous not in (None, 0):
        calculated_change = round((price - previous) / previous * 100, 2)
        if abs(calculated_change) > 35:
            reasons.append("涨跌幅超出常规保护阈值")
        if provided_change is not None and abs(provided_change - calculated_change) > 0.25:
            reasons.append("涨跌幅与价格计算结果不一致")
    return {
        "valid": not reasons,
        "reasons": reasons,
        "price": price,
        "previous_close": previous,
        "change_pct": calculated_change if calculated_change is not None else provided_change,
        "open": parse_market_number(quote.get("open")),
        "volume": parse_market_number(quote.get("volume")),
    }


def analyze_market_snapshot(
    snapshot: dict[str, Any],
    history: list[dict[str, Any]] | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    """Turn a quote snapshot into bounded, explainable research observations."""
    now = now or datetime.now(timezone.utc)
    history = history if history is not None else list_market_history(limit=30)
    checked_at = str(snapshot.get("checked_at") or "").strip()
    checked_dt = _sub2api_timestamp(checked_at)
    age_seconds = max(0, int((now - checked_dt).total_seconds())) if checked_dt else None
    if checked_dt is None:
        freshness = {"status": "unknown", "label": "没有同步时间"}
    elif age_seconds is not None and age_seconds <= 15 * 60:
        freshness = {"status": "fresh", "label": "数据新鲜"}
    elif age_seconds is not None and age_seconds <= 6 * 3600:
        freshness = {"status": "aging", "label": "数据较旧"}
    else:
        freshness = {"status": "stale", "label": "数据已过期"}
    freshness.update({"checked_at": checked_at, "age_seconds": age_seconds})

    watchlist = [item for item in snapshot.get("watchlist", []) if isinstance(item, dict) and item.get("symbol")]
    quotes = [item for item in snapshot.get("quotes", []) if isinstance(item, dict) and item.get("symbol")]
    quote_map = {market_symbol_key(item.get("symbol")): item for item in quotes}
    missing_symbols = [market_symbol_key(item.get("symbol")) for item in watchlist if market_symbol_key(item.get("symbol")) not in quote_map]
    quality_by_symbol: dict[str, dict[str, Any]] = {}
    anomalies: list[dict[str, Any]] = []
    valid_quotes: list[dict[str, Any]] = []
    for quote in quotes:
        symbol = market_symbol_key(quote.get("symbol"))
        quality = market_quote_quality(quote)
        quality_by_symbol[symbol] = quality
        if quality["valid"]:
            valid_quotes.append(quote)
        else:
            anomalies.append({"symbol": symbol, "name": quote.get("name") or symbol.upper(), "reasons": quality["reasons"]})

    prior_candidates = []
    for item in history:
        item_checked_at = str(item.get("checked_at") or "").strip()
        if not item_checked_at or market_timestamp_key(item_checked_at) == market_timestamp_key(checked_at):
            continue
        item_dt = _sub2api_timestamp(item_checked_at)
        if checked_dt and item_dt and item_dt <= checked_dt:
            prior_candidates.append((item_dt, item))
        elif not checked_dt:
            prior_candidates.append((item_dt or datetime.min.replace(tzinfo=timezone.utc), item))
    prior_snapshot = max(prior_candidates, key=lambda pair: pair[0])[1] if prior_candidates else None
    prior_quotes = {
        market_symbol_key(item.get("symbol")): item
        for item in (prior_snapshot or {}).get("quotes", [])
        if isinstance(item, dict) and item.get("symbol")
    }
    signals: list[dict[str, Any]] = []
    for quote in valid_quotes:
        symbol = market_symbol_key(quote.get("symbol"))
        quality = quality_by_symbol[symbol]
        change_pct = quality.get("change_pct")
        factors: list[str] = []
        if isinstance(change_pct, (int, float)):
            if change_pct <= -3:
                observation = "相对昨收明显走弱"
            elif change_pct >= 3:
                observation = "相对昨收明显走强"
            else:
                observation = "相对昨收变化有限"
            factors.append(f"日涨跌 {change_pct:+.2f}%")
        else:
            observation = "涨跌幅缺失，暂不判断方向"
        open_price = quality.get("open")
        if isinstance(open_price, (int, float)) and open_price > 0 and isinstance(quality.get("price"), (int, float)):
            open_change = round((quality["price"] - open_price) / open_price * 100, 2)
            factors.append(f"相对开盘 {open_change:+.2f}%")
        if quality.get("volume") is None:
            factors.append("成交量缺失")
        prior_delta = None
        prior = prior_quotes.get(symbol)
        prior_price = parse_market_number((prior or {}).get("price"))
        if prior_price and quality.get("price"):
            prior_delta = round((quality["price"] - prior_price) / prior_price * 100, 2)
            factors.append(f"较上一快照 {prior_delta:+.2f}%")
        factor_analysis = analyze_market_factors(symbol, snapshot, history, quality)
        factors.extend(factor_analysis["factor_labels"])
        signals.append({
            "symbol": symbol,
            "name": quote.get("name") or symbol.upper(),
            "observation": observation,
            "change_pct": change_pct,
            "prior_delta_pct": prior_delta,
            "factors": factors,
            "factor_details": factor_analysis["factors"],
            "data_quality": factor_analysis["data_quality"],
            "research_tasks": factor_analysis["research_tasks"],
        })

    warnings: list[str] = []
    if freshness["status"] in {"stale", "unknown", "aging"}:
        warnings.append(f"{freshness['label']}，请刷新后再做判断")
    if missing_symbols:
        warnings.append(f"{len(missing_symbols)} 只自选未返回有效报价")
    if anomalies:
        warnings.append(f"{len(anomalies)} 条报价触发异常保护")
    if not watchlist:
        summary = "还没有自选股票，先添加标的再开始研究。"
    elif not valid_quotes:
        summary = "当前没有可用于研究的有效报价，已保留原有快照。"
    elif warnings:
        summary = f"已读取 {len(valid_quotes)}/{len(watchlist)} 只自选；当前需要关注数据质量或新鲜度。"
    else:
        summary = f"已读取 {len(valid_quotes)} 只自选；可基于日涨跌、趋势、波动和成交活跃度做观察。"
    factor_total = sum(len(signal.get("factor_details") or []) for signal in signals)
    factor_ready = sum(
        1
        for signal in signals
        for factor in (signal.get("factor_details") or [])
        if factor.get("status") == "ok"
    )
    quality_by_signal = [signal.get("data_quality") or {} for signal in signals]
    coverage_days = max((float(item.get("coverage_days") or 0) for item in quality_by_signal), default=0.0)
    source_stabilities = {str(item.get("source_stability") or "unknown") for item in quality_by_signal}
    freshness_score = {"fresh": 1.0, "aging": 0.65, "stale": 0.25, "unknown": 0.0}.get(freshness["status"], 0.0)
    watchlist_symbols = {market_symbol_key(item.get("symbol")) for item in watchlist}
    valid_watchlist_quotes = [quote for quote in valid_quotes if market_symbol_key(quote.get("symbol")) in watchlist_symbols]
    quote_score = min(1.0, (len(valid_watchlist_quotes) / len(watchlist)) if watchlist else 0.0)
    factor_score = (factor_ready / factor_total) if factor_total else 0.0
    coverage_values = [float(item.get("coverage_days") or 0) for item in quality_by_signal if item.get("sample_count")]
    representative_coverage = statistics.median(coverage_values) if coverage_values else 0.0
    coverage_score = min(1.0, representative_coverage / 20.0) if representative_coverage else 0.0
    confidence_score = round(quote_score * 0.35 + freshness_score * 0.25 + factor_score * 0.25 + coverage_score * 0.15, 3)
    confidence = "high" if confidence_score >= 0.8 and factor_total and factor_ready == factor_total and freshness["status"] == "fresh" else "medium" if confidence_score >= 0.5 else "low"
    research_confidence = {
        "score": confidence_score,
        "label": confidence,
        "sample_count": sum(int(item.get("sample_count") or 0) for item in quality_by_signal),
        "valid_quote_count": len(valid_quotes),
        "rejected_quote_count": len(anomalies) + len(missing_symbols),
        "coverage_days": coverage_days,
        "freshness": freshness["status"],
        "factor_ready_count": factor_ready,
        "factor_total": factor_total,
        "source_stability": "unknown" if not source_stabilities or source_stabilities == {"unknown"} else "mixed" if "mixed" in source_stabilities or len(source_stabilities) > 1 else "stable",
        "explanation": "置信度综合有效报价、数据新鲜度、因子最小样本和时间覆盖；不代表收益概率。",
    }
    status = "warning" if not watchlist else "error" if not valid_quotes else "warning" if warnings else "ok"
    return {
        "status": status,
        "status_label": "暂无自选" if not watchlist else "行情不可用" if not valid_quotes else "需要关注" if warnings else "可研究",
        "summary": summary,
        "freshness": freshness,
        "source": str(snapshot.get("source") or "未知行情源"),
        "watchlist_count": len(watchlist),
        "quote_count": len(quotes),
        "valid_quote_count": len(valid_quotes),
        "missing_symbols": missing_symbols,
        "anomalies": anomalies,
        "warnings": warnings,
        "signals": signals,
        "research_confidence": research_confidence,
        "risk_note": "这些是基于公开快照的研究线索，不构成投资建议，也不会自动下单。",
    }


def _market_history_points(
    symbol: str,
    snapshot: dict[str, Any],
    history: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return de-duplicated chronological quote points for one symbol."""
    by_time: dict[str, dict[str, Any]] = {}
    # The current JSON snapshot wins over a database row with the same time.
    for entry in [*history, snapshot]:
        checked_at = str(entry.get("checked_at") or "").strip()
        if not checked_at:
            continue
        timestamp_key = market_timestamp_key(checked_at)
        for quote in entry.get("quotes", []):
            if not isinstance(quote, dict):
                continue
            if market_symbol_key(quote.get("symbol")) != market_symbol_key(symbol):
                continue
            price = parse_market_number(quote.get("price"))
            if price is None or price <= 0:
                continue
            by_time[timestamp_key] = {
                "checked_at": checked_at,
                "price": price,
                "volume": parse_market_number(quote.get("volume")),
                "source": str(entry.get("source") or "unknown"),
            }
    return sorted(
        by_time.values(),
        key=lambda item: _sub2api_timestamp(item["checked_at"]) or datetime.min.replace(tzinfo=timezone.utc),
    )


def _market_factor_meta(
    *,
    label: str,
    points: list[dict[str, Any]],
    value: Any = None,
    unit: str = "",
    observation: str = "",
    missing_reason: str = "",
    minimum_samples: int = 0,
) -> dict[str, Any]:
    if not missing_reason and minimum_samples and len(points) < minimum_samples:
        missing_reason = f"至少需要 {minimum_samples} 个不同时间的有效样本，当前只有 {len(points)} 个"
    coverage_days = 0.0
    if len(points) >= 2:
        parsed = [_sub2api_timestamp(item.get("checked_at")) for item in points]
        parsed = [item for item in parsed if item]
        if len(parsed) >= 2:
            coverage_days = round(max(0.0, (parsed[-1] - parsed[0]).total_seconds() / 86400), 2)
    return {
        "key": label,
        "label": label,
        "status": "ok" if not missing_reason else "missing",
        "value": value,
        "unit": unit,
        "observation": observation,
        "sample_count": len(points),
        "minimum_samples": minimum_samples,
        "coverage_days": coverage_days,
        "data_from": points[0]["checked_at"] if points else "",
        "data_to": points[-1]["checked_at"] if points else "",
        "missing_reason": missing_reason,
    }


def analyze_market_factors(
    symbol: str,
    snapshot: dict[str, Any],
    history: list[dict[str, Any]],
    quality: dict[str, Any],
) -> dict[str, Any]:
    """Calculate bounded factors from local snapshots, never from model guesses.

    The public quote source currently provides price and volume only. Valuation,
    fundamentals and technical indicators that need a longer time series remain
    explicitly absent instead of being inferred.
    """
    points = _market_history_points(symbol, snapshot, history)
    price_points = [point for point in points if isinstance(point.get("price"), (int, float))]
    volume_points = [point for point in points if isinstance(point.get("volume"), (int, float)) and point["volume"] >= 0]
    factor_labels: list[str] = []
    research_tasks: list[dict[str, Any]] = []

    if len(price_points) >= 2:
        start_price = price_points[0]["price"]
        end_price = price_points[-1]["price"]
        trend_change = round((end_price - start_price) / start_price * 100, 2) if start_price else None
        trend_state = "up" if trend_change is not None and trend_change >= 3 else "down" if trend_change is not None and trend_change <= -3 else "flat"
        trend_text = {
            "up": "样本区间价格上行",
            "down": "样本区间价格下行",
            "flat": "样本区间价格变化有限",
        }[trend_state]
        trend = _market_factor_meta(
            label="趋势",
            points=price_points,
            value=trend_change,
            unit="%",
            observation=trend_text,
            minimum_samples=3,
        )
        trend.update({"state": trend_state, "start_price": start_price, "end_price": end_price})
        if trend.get("status") == "ok" and trend_state in {"up", "down"}:
            factor_labels.append(f"区间趋势 {trend_change:+.2f}%")
            research_tasks.append({"factor": f"trend_{trend_state}", "label": "趋势变化", "message": trend_text, "value": trend_change})
        # 单日异动：最新一个价格点相对前一个样本的涨跌幅超过 ±5% 时单独提示，
        # 与区间趋势区分开（单日异动往往值得当天关注）。
        if trend.get("status") == "ok" and len(price_points) >= 2 and price_points[-2].get("price"):
            last_change = round((price_points[-1]["price"] - price_points[-2]["price"]) / price_points[-2]["price"] * 100, 2)
            if abs(last_change) >= 5:
                day_state = "up" if last_change > 0 else "down"
                day_text = f"最新样本较前一记录 {last_change:+.2f}%，属于明显异动，建议关注当天动态与消息面。"
                factor_labels.append(f"单日异动 {last_change:+.2f}%")
                research_tasks.append({"factor": f"daily_spike_{day_state}", "label": "单日异动", "message": day_text, "value": last_change})
    else:
        trend = _market_factor_meta(label="趋势", points=price_points, missing_reason="至少需要 3 个不同时间的有效价格样本", minimum_samples=3)
        trend["state"] = "unknown"

    returns: list[float] = []
    for previous, current in zip(price_points, price_points[1:]):
        if previous["price"]:
            returns.append((current["price"] - previous["price"]) / previous["price"] * 100)
    if len(price_points) >= 4 and len(returns) >= 3:
        volatility = round(statistics.pstdev(returns), 2)
        volatility_state = "high" if volatility >= 3 else "normal"
        volatility_text = "样本间价格波动偏高" if volatility_state == "high" else "样本间价格波动暂未偏高"
        volatility_factor = _market_factor_meta(label="波动", points=price_points, value=volatility, unit="%", observation=volatility_text, minimum_samples=4)
        volatility_factor.update({"state": volatility_state, "return_samples": len(returns)})
        if volatility_factor.get("status") == "ok" and volatility_state == "high":
            factor_labels.append(f"波动 {volatility:.2f}%")
            research_tasks.append({"factor": "high_volatility", "label": "波动偏高", "message": volatility_text, "value": volatility})
    else:
        volatility_factor = _market_factor_meta(label="波动", points=price_points, missing_reason="至少需要 4 个不同时间的有效价格样本", minimum_samples=4)
        volatility_factor.update({"state": "unknown", "return_samples": len(returns)})

    if len(volume_points) >= 3:
        latest_volume = volume_points[-1]["volume"]
        baseline = [point["volume"] for point in volume_points[:-1]]
        median_volume = statistics.median(baseline) if baseline else None
        volume_ratio = round(latest_volume / median_volume, 2) if median_volume and median_volume > 0 else None
        if volume_ratio is None:
            activity_factor = _market_factor_meta(label="成交活跃度", points=volume_points, missing_reason="历史成交量基准为 0，无法比较")
            activity_factor.update({"state": "unknown"})
        else:
            activity_state = "high" if volume_ratio >= 1.5 else "low" if volume_ratio <= 0.67 else "normal"
            activity_text = {"high": "最新成交量高于历史中位数", "low": "最新成交量低于历史中位数", "normal": "最新成交量接近历史中位数"}[activity_state]
            activity_factor = _market_factor_meta(label="成交活跃度", points=volume_points, value=volume_ratio, unit="x", observation=activity_text, minimum_samples=3)
            activity_factor.update({"state": activity_state, "latest_volume": latest_volume, "baseline_volume": median_volume})
            if activity_factor.get("status") == "ok" and activity_state in {"high", "low"}:
                factor_labels.append(f"成交量 {volume_ratio:.2f}x")
                research_tasks.append({"factor": f"volume_{activity_state}", "label": "成交活跃度变化", "message": activity_text, "value": volume_ratio})
    else:
        activity_factor = _market_factor_meta(label="成交活跃度", points=volume_points, missing_reason="至少需要 3 个不同时间的有效成交量样本", minimum_samples=3)
        activity_factor.update({"state": "unknown"})

    factor_details = [trend, volatility_factor, activity_factor]
    data_quality = {
        "sample_count": len(points),
        "valid_price_count": len(price_points),
        "valid_volume_count": len(volume_points),
        "data_from": points[0]["checked_at"] if points else "",
        "data_to": points[-1]["checked_at"] if points else "",
        "coverage_days": max((float(factor.get("coverage_days") or 0) for factor in factor_details), default=0.0),
        "source": str(snapshot.get("source") or "unknown"),
        "source_stability": "unknown" if not points else "stable" if len({str(point.get("source") or "unknown") for point in points}) == 1 else "mixed",
        "missing_factors": [factor["label"] for factor in factor_details if factor.get("status") == "missing"],
        "note": "公开行情快照目前只提供价格和成交量；因子样本不足时不做方向性判断。",
    }
    return {"factors": factor_details, "factor_labels": factor_labels, "research_tasks": research_tasks, "data_quality": data_quality}


def evaluate_market_observations(
    snapshot: dict[str, Any] | None = None,
    *,
    create_records: bool = False,
) -> dict[str, Any]:
    """Turn material factor signals into deduplicated local research tasks."""
    snapshot = snapshot or load_market_snapshot()
    history = list_market_history(limit=60)
    if snapshot.get("checked_at"):
        record_market_snapshot(snapshot)
        history = list_market_history(limit=60)
    analysis = analyze_market_snapshot(snapshot, history)
    candidates: list[dict[str, Any]] = []
    created: list[dict[str, Any]] = []
    existing_items = list_work_items("all", "market") if create_records else []
    artifact = list_artifacts("market")[0] if create_records and list_artifacts("market") else None
    for signal in analysis.get("signals", []):
        for task in signal.get("research_tasks", []):
            factor = str(task.get("factor") or "observation")
            observation_key = f"market:{signal.get('symbol')}:{factor}"
            candidate = {
                "observation_key": observation_key,
                "symbol": signal.get("symbol", ""),
                "name": signal.get("name", ""),
                "factor": factor,
                "title": f"观察 {signal.get('name') or signal.get('symbol')} · {task.get('label') or '行情变化'}",
                "message": str(task.get("message") or "基于当前样本形成研究观察。"),
                "value": task.get("value"),
                "checked_at": analysis.get("freshness", {}).get("checked_at", ""),
                "source": analysis.get("source", ""),
            }
            candidates.append(candidate)
            if not create_records:
                continue
            # Keep one task per symbol/factor state even after completion. A
            # refresh must not recreate the same observation endlessly; a
            # changed factor state gets a different key and can be tracked.
            existing = next(
                (item for item in existing_items if item.get("metadata", {}).get("observation_key") == observation_key),
                None,
            )
            if existing:
                created.append({"candidate": candidate, "work_item": existing, "created": False})
                continue
            item = create_work_item_record(
                title=candidate["title"],
                description=f"{candidate['message']} 数据时间：{candidate['checked_at'] or '未知'}。请在后续快照中复核，不构成买卖指令。",
                kind="research_observation",
                status="open",
                priority="normal",
                source_project="market",
                target_project="inbox",
                metadata={
                    "observation_key": observation_key,
                    "factor": factor,
                    "symbol": candidate["symbol"],
                    "checked_at": candidate["checked_at"],
                    "source": candidate["source"],
                    "agent": "quantitative_research_agent",
                },
            )
            relation = None
            if artifact:
                relation = create_relation_record(
                    from_type="artifact",
                    from_id=str(artifact["id"]),
                    to_type="work_item",
                    to_id=str(item["id"]),
                    relation_type="research_observation_from_snapshot",
                    metadata={"observation_key": observation_key, "checked_at": candidate["checked_at"]},
                )
            try:
                create_notification_record(
                    title=candidate["title"],
                    body=f"{candidate['message']} · 数据时间：{candidate['checked_at'] or '未知'}",
                    project_id="market",
                    kind="research_observation",
                    level="info",
                    href="/projects/market#market-observations",
                    event_key=f"market-observation:{observation_key}",
                    dedupe_seconds=0,
                )
            except Exception:
                log.debug("忽略异常（evaluate_market_observations）", exc_info=True)
            existing_items.append(item)
            created.append({"candidate": candidate, "work_item": item, "relation": relation, "created": True})
    return {"analysis": analysis, "candidates": candidates, "created": created}


def add_market_symbol_to_watchlist(symbol: str) -> dict[str, Any]:
    normalized = normalize_market_symbol(symbol)
    if not normalized:
        raise ValueError(f"无法识别股票代码：{symbol}")
    values = load_market_watchlist()
    existing = {item.get("symbol") for item in values}
    added = normalized not in existing
    if added:
        values.append({"symbol": normalized})
        save_market_watchlist(values)
        snapshot = load_market_snapshot()
        snapshot["watchlist"] = values
        save_market_snapshot(snapshot)
    return {"symbol": normalized, "added": added, "watchlist": values}


