AGENT_RESULT_CONTRACT_VERSION = "1.1"


def _is_markdown_table_divider(line: str) -> bool:
    """|---|:--:|---| 这种表格分隔行。

    前端 static/markdown.js 里有同名判断，两边必须保持一致：一边认成表格、
    另一边认成普通行的话，正文渲染出一张表，「结构化结果」里却是一堆碎条目。
    """
    text = str(line or "").strip()
    return bool(text) and "-" in text and re.fullmatch(r"\|?[\s:|-]*-[\s:|-]*\|?", text) is not None


AGENT_RESULT_SECTION_ALIASES: dict[str, tuple[str, ...]] = {
    "summary": ("结论", "一句话结论", "总体判断", "摘要"),
    "facts": ("事实", "已知事实", "事实与证据", "已知信息"),
    "judgement": ("判断", "判断与假设", "推断", "分析"),
    "evidence": ("证据", "来源与证据", "数据依据", "依据"),
    "risks": ("风险", "不确定性", "缺口", "待验证"),
    "actions": ("动作", "可直接执行的本地动作", "已执行动作", "需要我确认的动作"),
    "next_steps": ("下一步", "后续", "验证计划", "行动计划"),
}


def _contract_id_list(values: Any) -> list[str]:
    """Normalize trace IDs without assuming every store uses the same type."""
    if values is None:
        return []
    if not isinstance(values, (list, tuple, set)):
        values = [values]
    result: list[str] = []
    for value in values:
        if isinstance(value, dict):
            value = value.get("id") or value.get("artifact_id") or value.get("work_item_id") or value.get("relation_id")
        if value in (None, ""):
            continue
        normalized = str(value)
        if normalized not in result:
            result.append(normalized)
    return result[:100]


def _contract_source_ref(value: Any) -> dict[str, Any] | None:
    """Keep source references small, stable and safe to render in the UI."""
    if not isinstance(value, dict):
        value = {"label": str(value or "")}
    source_id = value.get("source_id") or value.get("id") or value.get("artifact_id") or value.get("work_item_id") or value.get("relation_id") or value.get("crawl_run_id")
    source_type = value.get("source_type") or value.get("type")
    if not source_type:
        source_type = "artifact" if value.get("artifact_id") else "work_item" if value.get("work_item_id") else "relation" if value.get("relation_id") else "source"
    label = value.get("label") or value.get("title") or value.get("name") or value.get("source") or value.get("url") or value.get("link") or source_id or "未命名来源"
    locator = value.get("locator") or value.get("url") or value.get("link") or value.get("path") or ""
    data_as_of = value.get("data_as_of") or value.get("data_at") or value.get("fetched_at") or value.get("checked_at") or value.get("published_at") or value.get("updated_at") or value.get("created_at") or ""
    ref = {
        "type": str(source_type)[:60],
        "label": clip(str(label), 240),
    }
    if source_id not in (None, ""):
        ref["id"] = str(source_id)
    if locator:
        ref["locator"] = clip(str(locator), 1_000)
    if data_as_of:
        ref["data_as_of"] = clip(str(data_as_of), 80)
    if value.get("content_hash"):
        ref["content_hash"] = clip(str(value.get("content_hash")), 128)
    if value.get("source_quality") or value.get("quality"):
        ref["source_quality"] = value.get("source_quality") or value.get("quality")
    for key in ("line_start", "line_end"):
        if value.get(key) not in (None, "", 0):
            try:
                ref[key] = int(value[key])
            except (TypeError, ValueError):
                pass
    return ref


def _contract_source_refs(values: Any) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for value in values or []:
        ref = _contract_source_ref(value)
        if not ref:
            continue
        key = (str(ref.get("type", "")), str(ref.get("id", "")), str(ref.get("locator", "")))
        if key in seen:
            continue
        seen.add(key)
        refs.append(ref)
    return refs[:50]


def _contract_source_coverage(refs: list[dict[str, Any]]) -> dict[str, Any]:
    """Summarize whether an Agent result has locatable, timestamped sources.

    This is intentionally descriptive rather than a truth score: a complete
    locator does not make a claim true, but a missing locator makes review and
    replay needlessly expensive.
    """
    counts: dict[str, int] = {}
    with_locator = 0
    with_data_time = 0
    for ref in refs:
        source_type = str(ref.get("type") or "source")
        counts[source_type] = counts.get(source_type, 0) + 1
        if ref.get("locator") or ref.get("id"):
            with_locator += 1
        if ref.get("data_as_of"):
            with_data_time += 1
    total = len(refs)
    if not total:
        status = "missing"
    elif with_locator == total and with_data_time == total:
        status = "complete"
    else:
        status = "partial"
    return {
        "status": status,
        "total": total,
        "with_locator": with_locator,
        "with_data_time": with_data_time,
        "types": counts,
    }


def agent_context_result_metadata(context: dict[str, Any] | None) -> dict[str, Any]:
    """Extract traceable IDs and freshness from the read-only Agent snapshot."""
    if not isinstance(context, dict):
        return {"source_refs": [], "artifact_ids": [], "work_item_ids": [], "relation_ids": [], "data_as_of": ""}
    project_context = context.get("project_context") if isinstance(context.get("project_context"), dict) else context
    shared_context = context.get("shared_context") if isinstance(context.get("shared_context"), dict) else {}
    refs: list[dict[str, Any]] = []
    artifact_ids: list[str] = []
    work_item_ids: list[str] = []
    relation_ids: list[str] = []
    timestamps: list[str] = []

    source = project_context.get("source")
    if source:
        refs.append({"type": "context", "label": source, "locator": source})

    def add_item(item: Any, kind: str) -> None:
        if not isinstance(item, dict):
            return
        item_id = item.get("id") or item.get(f"{kind}_id")
        if kind == "artifact" and item_id is not None:
            artifact_ids.append(str(item_id))
        elif kind == "work_item" and item_id is not None:
            work_item_ids.append(str(item_id))
        elif kind == "relation" and item_id is not None:
            relation_ids.append(str(item_id))
        ref = {"type": kind, "id": item_id, "title": item.get("title") or item.get("name"), "source": item.get("source"), "url": item.get("url") or item.get("link"), "path": item.get("path")}
        for key in ("data_as_of", "data_at", "fetched_at", "checked_at", "published_at", "updated_at", "created_at"):
            if item.get(key):
                ref[key] = item[key]
                timestamps.append(str(item[key]))
                break
        if item_id is not None or ref.get("title") or ref.get("source") or ref.get("url") or ref.get("path"):
            refs.append(ref)

    for item in shared_context.get("recent_artifacts") or []:
        add_item(item, "artifact")
    for item in shared_context.get("open_work_items") or []:
        add_item(item, "work_item")
    request_context = context.get("request_context") if isinstance(context.get("request_context"), dict) else {}
    for key, kind in (("artifact_ids", "artifact"), ("work_item_ids", "work_item"), ("relation_ids", "relation")):
        for item_id in request_context.get(key) or []:
            add_item({"id": item_id}, kind)
    for key in ("data_as_of", "data_at", "fetched_at", "checked_at", "published_at", "updated_at", "created_at"):
        value = project_context.get(key)
        if value:
            timestamps.append(str(value))

    data_as_of = max(set(timestamps)) if timestamps else ""
    return {
        "source_refs": _contract_source_refs(refs),
        "artifact_ids": _contract_id_list(artifact_ids),
        "work_item_ids": _contract_id_list(work_item_ids),
        "relation_ids": _contract_id_list(relation_ids),
        "data_as_of": data_as_of,
    }


def agent_result_contract(
    project_id: str,
    answer: str,
    *,
    actions: list[dict[str, Any]] | None = None,
    evidence: list[dict[str, Any]] | None = None,
    source_refs: list[dict[str, Any]] | None = None,
    data_as_of: str = "",
    artifact_ids: list[Any] | None = None,
    work_item_ids: list[Any] | None = None,
    relation_ids: list[Any] | None = None,
    run_id: str = "",
    session_id: str = "",
    replay: dict[str, Any] | None = None,
    execution_plan: dict[str, Any] | None = None,
    memory_refs: list[dict[str, Any]] | None = None,
    memory_updates: list[dict[str, Any]] | None = None,
    memory_context_stats: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Normalize free-form Agent Markdown into a stable, auditable envelope.

    Agents still return readable Markdown to users.  This lightweight parser
    makes the same answer machine-readable without trusting a model to emit
    valid JSON, and keeps the original answer intact for display.
    """
    sections: dict[str, list[str]] = {key: [] for key in AGENT_RESULT_SECTION_ALIASES}
    current = "summary"
    # 逐行切条目，但表格和围栏代码块必须整块保留。
    # 之前是纯粹按行切的，于是模型写的一张表在「结构化结果」里会散成一堆条目——
    # 连 |---|---| 这行分隔线都单独成了一条，读起来完全是乱码。
    raw_lines = str(answer or "").splitlines()
    index = 0
    while index < len(raw_lines):
        line = raw_lines[index].strip()
        if not line:
            index += 1
            continue

        if line.startswith("```"):
            block = [raw_lines[index]]
            index += 1
            while index < len(raw_lines) and not raw_lines[index].strip().startswith("```"):
                block.append(raw_lines[index])
                index += 1
            if index < len(raw_lines):
                block.append(raw_lines[index])
                index += 1
            sections[current].append("\n".join(block))
            continue

        if "|" in line and index + 1 < len(raw_lines) and _is_markdown_table_divider(raw_lines[index + 1]):
            block = [raw_lines[index], raw_lines[index + 1]]
            index += 2
            while index < len(raw_lines) and "|" in raw_lines[index] and raw_lines[index].strip():
                block.append(raw_lines[index])
                index += 1
            sections[current].append("\n".join(block))
            continue

        # 落单的分隔线（表格被截断、或模型写了个没表头的分隔行）不该变成条目。
        if _is_markdown_table_divider(line) or re.fullmatch(r"[-*_]{3,}", line):
            index += 1
            continue

        heading = re.sub(r"^[#\d.、)）\-\s]+", "", line).rstrip("：:")
        matched = next((key for key, aliases in AGENT_RESULT_SECTION_ALIASES.items() if heading in aliases), None)
        index += 1
        if matched:
            current = matched
            continue
        # 顺手削掉行首的列表符号：面板里本来就带项目符号，留着会变成「· 1. 先复现」。
        sections[current].append(re.sub(r"^(?:[•*\-]|\d+[.)])\s*", "", line))
    # summary 是要塞进一行标题里的，表格和代码块拼进去只会是一串竖线。
    summary_lines = [item for item in sections["summary"] if "\n" not in item]
    summary = " ".join(summary_lines) or clip(str(answer).strip().splitlines()[0] if str(answer).strip() else "", 500)
    citations: list[dict[str, str]] = []
    seen_citations: set[str] = set()
    for raw_line in str(answer or "").splitlines():
        for url in re.findall(r"https?://[^\s)\]>]+", raw_line):
            clean_url = url.rstrip("。，、；;:：")
            if clean_url and clean_url not in seen_citations:
                seen_citations.add(clean_url)
                citations.append({"type": "url", "value": clean_url, "label": _hostname(clean_url)})
        for marker in re.findall(r"\[来源[：:]\s*([^\]]+)\]", raw_line):
            value = marker.strip()
            key = f"source:{value}"
            if value and key not in seen_citations:
                seen_citations.add(key)
                citations.append({"type": "source", "value": value, "label": "来源标记"})
    action_summary = []
    action_artifact_ids: list[Any] = []
    action_work_item_ids: list[Any] = []
    action_relation_ids: list[Any] = []
    for action in actions or []:
        action_result = action.get("result") if isinstance(action.get("result"), dict) else {}
        action_artifact_ids.extend(action_result.get("artifact_ids") or ([action_result.get("artifact_id")] if action_result.get("artifact_id") else []))
        action_work_item_ids.extend(action_result.get("work_item_ids") or ([action_result.get("work_item_id")] if action_result.get("work_item_id") else []))
        action_relation_ids.extend(action_result.get("relation_ids") or ([action_result.get("relation_id")] if action_result.get("relation_id") else []))
        action_summary.append({
            "id": action.get("id", ""),
            "name": action.get("name") or action.get("tool", "Agent 动作"),
            "tool": action.get("tool", ""),
            "status": action.get("status", "pending"),
            "requires_confirmation": bool(action.get("requires_confirmation")),
        })
    normalized_refs = _contract_source_refs([*(evidence or []), *(source_refs or [])])
    source_coverage = _contract_source_coverage(normalized_refs)
    derived_data_as_of = data_as_of or next((str(item.get("data_as_of")) for item in normalized_refs if item.get("data_as_of")), "")
    review_reasons: list[str] = []
    if not normalized_refs and not citations:
        review_reasons.append("没有绑定可回溯来源")
    if not derived_data_as_of:
        review_reasons.append("没有数据时间")
    freshness = {
        "status": "timestamped" if derived_data_as_of else "missing",
        "data_as_of": derived_data_as_of,
        "needs_review": bool(review_reasons),
        "review_reasons": review_reasons,
    }
    replay_payload = dict(replay or {})
    replay_payload.setdefault("available", bool(run_id))
    replay_payload.setdefault("run_id", run_id)
    replay_payload.setdefault("session_id", session_id)
    if run_id:
        replay_payload.setdefault("href", f"/api/agent/{project_id}/runs/{run_id}")
    return {
        "schema_version": AGENT_RESULT_CONTRACT_VERSION,
        "agent_id": project_id,
        "agent_name": agent_display_name(project_id),
        "intent": clip(str((execution_plan or {}).get("intent") or ""), 160),
        "summary": clip(summary, 1_000),
        "sections": {key: values[:20] for key, values in sections.items()},
        "evidence": (evidence or [])[:30],
        "source_refs": normalized_refs,
        "source_coverage": source_coverage,
        "data_as_of": derived_data_as_of,
        "freshness": freshness,
        "needs_review": bool(review_reasons),
        "review_reasons": review_reasons,
        "artifact_ids": _contract_id_list([*(artifact_ids or []), *action_artifact_ids, *[item.get("id") for item in normalized_refs if item.get("type") == "artifact"]]),
        "work_item_ids": _contract_id_list([*(work_item_ids or []), *action_work_item_ids, *[item.get("id") for item in normalized_refs if item.get("type") == "work_item"]]),
        "relation_ids": _contract_id_list([*(relation_ids or []), *action_relation_ids, *[item.get("id") for item in normalized_refs if item.get("type") == "relation"]]),
        "run_id": str(run_id or ""),
        "session_id": str(session_id or ""),
        "replay": replay_payload,
        "execution_plan": dict(execution_plan) if isinstance(execution_plan, dict) else {},
        "tool_plan": (execution_plan or {}).get("tool_plan", [])[:30] if isinstance((execution_plan or {}).get("tool_plan", []), list) else [],
        "memory_refs": [
            {key: item.get(key) for key in ("id", "content", "scope", "project_id", "kind", "confidence", "pinned") if item.get(key) not in (None, "")}
            for item in (memory_refs or [])[:20]
            if isinstance(item, dict)
        ],
        "memory_context": {
            key: (bool((memory_context_stats or {}).get(key)) if key == "core_only" else max(0, int((memory_context_stats or {}).get(key) or 0)))
            for key in ("items", "chars", "pinned", "matched", "calls", "max_items", "max_chars", "core_only")
        },
        "memory_updates": [
            {key: item.get(key) for key in ("id", "content", "scope", "project_id", "kind", "status", "status_label", "learning_reason") if item.get(key) not in (None, "")}
            for item in (memory_updates or [])[:20]
            if isinstance(item, dict)
        ],
        "citations": citations[:30],
        "actions": action_summary,
        "original_answer": str(answer or ""),
    }


def available_child_agents() -> list[str]:
    return [item.get("id") for item in load_projects() if item.get("id") in AGENT_REGISTRY]


def route_child_agents(message: str, requested: list[str]) -> list[str]:
    children = set(AGENT_REGISTRY["workbench"].get("children", []))
    explicit = [item for item in requested if item in children and item in AGENT_REGISTRY]
    if explicit:
        return list(dict.fromkeys(explicit))
    return capability_graph_route(message, list(children))


def child_agent_system(project_id: str) -> str:
    capability = AGENT_REGISTRY.get(project_id, {})
    project = next((item for item in load_projects() if item.get("id") == project_id), {})
    playbook = AGENT_PLAYBOOKS.get(project_id, {})
    output_contract = "、".join(playbook.get("output", ["结论", "证据", "下一步", "风险"]))
    domain_guardrail = ""
    if project_id == "market":
        domain_guardrail = (
            "量化选股特别规则：股票名称只能使用实时快照中的 name-symbol 对应关系或工作台明确登记的本地映射；"
            "没有可验证代码时要说明缺口，不要猜代码。动作只允许来自用户原始消息中的明确标的，"
            "不能把当前已有自选、你的回答或其他子 Agent 提到的股票变成新动作。"
        )
    return (
        f"你是本地工作台中的「{capability.get('name', project.get('title', project_id))}」（{project_id}）子 Agent。"
        f"你的职责是：{project.get('description', '处理本项目相关任务')}。"
        f"当前能力状态：{capability.get('status', 'planned')}；可用工具声明：{', '.join(capability.get('tools', [])) or '无'}。"
        f"你的核心任务：{playbook.get('mission', '围绕上下文给出可执行结果')}。"
        f"执行流程：{playbook.get('workflow', '读取上下文→分析→给出下一步')}。"
        f"输出必须覆盖：{output_contract}。"
        "请尽量使用以下固定小标题输出：结论、事实与证据、判断与不确定性、风险/缺口、动作、下一步。"
        f"自动化边界：{playbook.get('autonomy', '只读分析；写入动作按权限确认')}。"
        f"{domain_guardrail}"
        "你只应基于传入的上下文回答，不要假装已经调用了未提供的工具；"
        "不要只给泛泛建议：每条结论都要绑定上下文中的证据、时间或缺口；如果数据不足，先指出缺口并给出最小补充动作。"
        "明确区分已知事实、推断、建议和需要用户确认的动作。使用简体中文，输出简洁、可执行的结果。"
    )


def market_symbols_from_text(value: str) -> list[str]:
    """Resolve only codes or locally verifiable stock names from user text.

    The LLM response is deliberately not accepted here. A model may mention
    an existing holding or speculate about a code; neither is user intent.
    """
    candidates = re.findall(
        r"(?<![a-z0-9])(?:sh|sz|bj)\d{6}(?!\d)|(?<!\d)\d{6}(?!\d)",
        (value or "").lower(),
    )
    symbols = []
    for candidate in candidates:
        normalized = normalize_market_symbol(candidate)
        if normalized and normalized not in symbols:
            symbols.append(normalized)
    aliases = {
        "传智教育": "sz003032",
        "传智": "sz003032",
        "长鑫科技": "sh688825",
    }
    for quote in load_market_snapshot().get("quotes", []):
        name = str(quote.get("name") or "").strip()
        symbol = normalize_market_symbol(str(quote.get("symbol") or ""))
        if name and symbol:
            aliases[name] = symbol
    lowered = str(value or "").lower()
    for name, symbol in aliases.items():
        if name.lower() in lowered and symbol not in symbols:
            symbols.append(symbol)
    return symbols


def extract_threshold_values(message: str) -> dict[str, float]:
    """Parse threshold mentions like 磁盘 90 / 内存 95 / 负载 8 into bounded values."""
    values: dict[str, float] = {}
    text = message.lower()
    patterns = [
        ("disk", r"磁盘[^\d]{0,10}(\d{1,3})"),
        ("memory", r"内存[^\d]{0,10}(\d{1,3})"),
        ("load", r"负载[^\d]{0,10}(\d{1,3}(?:\.\d)?)"),
    ]
    for key, pattern in patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        try:
            number = float(match.group(1))
        except ValueError:
            continue
        if key == "load":
            if 0 <= number <= 1000:
                values[f"load_warn"] = max(0, number - 4)
                values[f"load_critical"] = number
        else:
            if 0 <= number <= 100:
                values[f"{key}_warn"] = max(0, number - 10)
                values[f"{key}_critical"] = number
    return values


# 否定、疑问、转述——这三种句子里出现动作关键词，都不代表用户要执行它。
# 原来的推断只做子串包含：「最近不用太关注传智教育了」会命中「关注」并把
# 传智教育加进自选；「要不要记录一下？」会写收件箱。
NON_IMPERATIVE_PATTERNS = (
    re.compile(r"(不用|不要|别|无需|不必|没必要|不想|不需要)[^，。；\n]{0,8}(记录|记一下|沉淀|关注|添加|写入|保存)"),
    re.compile(r"(要不要|是否需要|需不需要|该不该|能不能|可不可以).{0,12}[?？]?$"),
    re.compile(r"[?？]\s*$"),
    re.compile(r"(他说|她说|别人说|同事说|之前说过|听说)"),
)


def action_intent_is_imperative(message: str) -> bool:
    """判断这句话是不是真的在要求执行，而不是在否定、提问或转述。"""
    text = str(message or "").strip()
    if not text:
        return False
    return not any(pattern.search(text) for pattern in NON_IMPERATIVE_PATTERNS)


def infer_agent_actions(project_id: str, message: str, answer: str) -> list[dict[str, Any]]:
    """Infer only narrowly-scoped, reversible local actions from an Agent turn.

    This is intentionally conservative: only explicit, reversible local
    actions are inferred (capture, note creation, watchlist addition). Server
    changes, trading, deletion and external communication are never inferred here.
    """
    # 关键词命中不等于用户要求执行：否定、疑问、转述都会命中同一批词。
    if not action_intent_is_imperative(message):
        return []
    if project_id == "inbox":
        capture_words = ("记录", "记一下", "放进收件箱", "保存到收件箱", "收进去")
        if any(word in message for word in capture_words) and not any(word in message for word in ("查询", "查看", "有哪些")):
            content = re.sub(r"^(帮我|请|麻烦你)?\s*(记录一下|记一下|记录|放进收件箱|保存到收件箱|收进去)?\s*[:：，,]?\s*", "", message.strip()).strip()
            if content:
                return [{
                    "name": "写入收件箱",
                    "tool": "inbox.capture",
                    "risk": runtime_tool_policy("inbox_capture")["risk"],
                    "requires_confirmation": runtime_tool_policy("inbox_capture")["mode"] == "confirm",
                    "arguments": {"content": content, "kind": "task" if "待办" in message or "任务" in message else "note", "tags": "Agent记录"},
                }]
    if project_id == "knowledge":
        save_words = ("沉淀", "写入知识库", "保存到知识库", "记成笔记", "写一篇笔记")
        if any(word in message for word in save_words):
            title = clip(re.sub(r"\s+", " ", message).strip(), 80) or "Agent 沉淀"
            return [{
                "name": "沉淀为本地知识笔记",
                "tool": "knowledge.note.create",
                "risk": runtime_tool_policy("knowledge_write")["risk"],
                "requires_confirmation": runtime_tool_policy("knowledge_write")["mode"] == "confirm",
                "arguments": {"title": title, "content": answer},
            }]
    if project_id == "server":
        # 阈值调整是本地低风险动作（只写本机 JSON，不碰服务器），可直接执行。
        threshold_words = ("阈值", "告警线", "警告线", "调到", "设置成", "改成")
        if any(word in message for word in ("磁盘", "内存", "负载")) and any(word in message for word in threshold_words):
            thresholds = extract_threshold_values(message)
            if thresholds:
                return [{
                    "name": "调整服务器监控阈值",
                    "tool": "server.thresholds.set",
                    # 策略表里 server_thresholds_set 一直写着 mode: confirm，
                    # 而这里生成的却是「低风险、不用确认」并直接落盘——
                    # 改告警阈值意味着以后可能收不到该收的告警，必须过人。
                    "risk": "medium",
                    "requires_confirmation": True,
                    "arguments": {"thresholds": thresholds},
                }]
        return []
    if project_id != "market":
        return []
    observation_words = ("观察任务", "研究任务", "观察清单", "生成观察", "生成研究任务", "建立观察")
    if any(word in message for word in observation_words):
        return [{
            "name": "生成行情观察任务",
            "tool": "market.observations.evaluate",
            "risk": "low",
            "requires_confirmation": False,
            "arguments": {},
        }]
    intent_words = ("添加", "加入", "放入", "自选", "关注", "监控")
    if not any(word in message for word in intent_words) or any(word in message for word in ("删除", "移除", "卖出", "买入", "下单")):
        return []
    # Never derive a write action from the model's answer. Only explicit codes
    # or a locally verifiable name in the user's message may become an action.
    symbols = market_symbols_from_text(message)
    return [
        {
            "name": "加入量化选股自选",
            "tool": "market.watchlist.add",
            # 这条是从「关注」两个字 + 股票别名表猜出来的，误判率最高的一条：
            # 「不用太关注 X 了」也会命中。加一道确认，猜错了也就是多一次点击。
            "risk": "low",
            "requires_confirmation": True,
            "arguments": {"symbol": symbol},
        }
        for symbol in symbols[:5]
    ]


def execute_agent_action(action_id: str, *, force: bool = False, parent_run_id: str = "") -> dict[str, Any]:
    action = get_agent_action_record(action_id)
    if not action:
        raise HTTPException(404, "Agent 动作不存在")
    if action["status"] == "executed":
        return action
    if action["status"] == "rejected":
        return action
    if action["requires_confirmation"] and not force:
        return action
    run = get_agent_run(action.get("run_id", "")) if action.get("run_id") else None
    if run and run.get("status") == "succeeded":
        return action
    if run and run.get("attempt", 1) >= run.get("max_attempts", 1) and run.get("status") == "failed":
        return action
    if not run:
        run = create_agent_run_record(
            project_id=action["project_id"],
            kind="action",
            title=action.get("name") or action.get("tool") or "Agent 动作",
            request={"action_id": action_id, "tool": action.get("tool"), "arguments": action.get("arguments", {})},
            parent_run_id=parent_run_id,
            max_attempts=3,
        )
        update_agent_action_record(action_id, run_id=run["id"])
        action = get_agent_action_record(action_id) or action
    elif run.get("status") == "failed":
        next_attempt = min(run.get("max_attempts", 3), run.get("attempt", 1) + 1)
        run = update_agent_run_record(run["id"], status="queued", attempt=next_attempt, error="") or run
        add_agent_run_event(run["id"], "retry_queued", f"第 {next_attempt} 次尝试已排队。", metadata={"action_id": action_id})
    update_agent_run_record(run["id"], status="running")
    add_agent_run_event(run["id"], "started", f"开始执行：{action.get('name') or action.get('tool')}", metadata={"action_id": action_id})
    try:
        # 确认门创建的动作用的是运行时工具名（notify / cloud_dev_generate /
        # cloud_dev_test 等）。此前这里只认旧的点号命名（market.watchlist.add、
        # inbox.capture…），两套名字零交集，确认后必然抛「工具尚未接入执行器」。
        # 运行时工具名直接回调 execute_react_tool(..., confirmed=True) 真正执行；
        # 旧点号分支保留兼容历史动作。
        if action["tool"] in REACT_TOOLS or action["tool"] in SUBAGENT_EXTRA_TOOLS:
            result = execute_react_tool(action["tool"], action.get("arguments") or {}, project_id=action["project_id"], run_id=run["id"], confirmed=True)
            if not isinstance(result, dict) or not result.get("ok"):
                raise RuntimeError(str((result or {}).get("error") or "工具执行失败"))
            result = result.get("result") if isinstance(result.get("result"), dict) else result
        elif action["tool"] == "market.watchlist.add":
            result = add_market_symbol_to_watchlist(action["arguments"].get("symbol", ""))
        elif action["tool"] == "market.observations.evaluate":
            result = evaluate_market_observations(create_records=True)
        elif action["tool"] == "inbox.capture":
            result = create_inbox_record(
                content=action["arguments"].get("content", ""),
                kind=action["arguments"].get("kind", "note"),
                tags=action["arguments"].get("tags", ""),
            )
        elif action["tool"] == "knowledge.note.create":
            result = write_knowledge_note(
                action["arguments"].get("title", "Agent 沉淀"),
                action["arguments"].get("content", ""),
            )
        elif action["tool"] == "server.thresholds.set":
            raw = action["arguments"].get("thresholds")
            values = raw if isinstance(raw, dict) else {}
            result = save_server_monitor_thresholds({key: float(value) for key, value in values.items() if key in DEFAULT_SERVER_THRESHOLDS})
        else:
            raise RuntimeError(f"工具尚未接入执行器：{action['tool']}")
        updated = update_agent_action_record(action_id, status="executed", result=result, run_id=run["id"]) or action
        update_agent_run_record(run["id"], status="succeeded", result={"action": updated})
        add_agent_run_event(run["id"], "succeeded", "动作执行完成。", level="success", metadata={"action_id": action_id})
        parent = get_agent_run(parent_run_id) if parent_run_id else None
        if not parent or parent.get("project_id") != "workbench":
            try:
                create_notification_record(
                    title=f"Agent 动作已完成：{updated.get('name') or updated.get('tool') or '动作'}",
                    body=agent_action_notice([updated]) or "动作已执行并记录。",
                    project_id=updated.get("project_id") or "workbench",
                    kind="agent_action",
                    level="success",
                    href=project_href(updated.get("project_id") or "workbench"),
                    event_key=f"agent-action-run:{run['id']}",
                    dedupe_seconds=0,
                )
            except Exception:
                log.debug("忽略异常（execute_agent_action）", exc_info=True)
        return updated
    except Exception as exc:
        error = str(exc)
        updated = update_agent_action_record(action_id, status="failed", result={"error": error}, run_id=run["id"]) or action
        update_agent_run_record(run["id"], status="failed", error=error, result={"action": updated})
        add_agent_run_event(run["id"], "failed", f"动作执行失败：{error}", level="error", metadata={"action_id": action_id})
        parent = get_agent_run(parent_run_id) if parent_run_id else None
        if not parent or parent.get("project_id") != "workbench":
            try:
                create_notification_record(
                    title=f"Agent 动作失败：{updated.get('name') or updated.get('tool') or '动作'}",
                    body=error,
                    project_id=updated.get("project_id") or "workbench",
                    kind="agent_action",
                    level="error",
                    href=project_href(updated.get("project_id") or "workbench"),
                    event_key=f"agent-action-run:{run['id']}",
                    dedupe_seconds=0,
                )
            except Exception:
                log.debug("忽略异常（execute_agent_action）", exc_info=True)
        return updated


def materialize_agent_actions(project_id: str, message: str, answer: str, *, parent_run_id: str = "") -> list[dict[str, Any]]:
    actions = []
    for definition in infer_agent_actions(project_id, message, answer):
        action = create_agent_action_record(project_id=project_id, **definition)
        if not action["requires_confirmation"]:
            action = execute_agent_action(action["id"], parent_run_id=parent_run_id)
        actions.append(action)
    return actions


def agent_action_notice(actions: list[dict[str, Any]]) -> str:
    notices = []
    for action in actions:
        result = action.get("result") or {}
        if action.get("status") == "executed" and action.get("tool") == "market.watchlist.add":
            symbol = result.get("symbol") or action.get("arguments", {}).get("symbol", "")
            state = "已在自选中" if not result.get("added", True) else "已加入自选"
            notices.append(f"✅ {state}：{str(symbol).upper()}")
        elif action.get("status") == "executed" and action.get("tool") == "market.observations.evaluate":
            result = action.get("result") or {}
            created = [item for item in result.get("created", []) if item.get("created")]
            candidates = result.get("candidates") or []
            notices.append(f"✅ 已生成行情观察任务：新增 {len(created)} 条，识别 {len(candidates)} 条")
        elif action.get("status") == "executed" and action.get("tool") == "inbox.capture":
            notices.append(f"✅ 已写入收件箱：{result.get('content') or action.get('arguments', {}).get('content', '')}")
        elif action.get("status") == "executed" and action.get("tool") == "knowledge.note.create":
            notices.append(f"✅ 已沉淀知识笔记：{result.get('title') or result.get('name') or action.get('arguments', {}).get('title', '')}")
        elif action.get("status") == "pending":
            notices.append(f"⏳ 待确认：{action.get('name', 'Agent 动作')}（动作 ID：{action.get('id')}）")
        elif action.get("status") == "failed":
            notices.append(f"⚠️ 执行失败：{action.get('name', 'Agent 动作')} · {(result.get('error') or '未知错误')}")
    return "\n".join(notices)


async def stream_agent_react_loop(
    *,
    project_id: str,
    run_id: str,
    messages: list[dict[str, Any]],
    tools: list[dict[str, Any]],
    tool_cache: dict[str, Any] | None = None,
    max_rounds: int = AGENT_MAX_TOOL_ROUNDS,
):
    """流式版 ReAct 循环：工具轮一次性执行，最终回答轮真流式输出。

    与 run_agent_react_loop 同语义（工具执行、事件流、回喂），区别：
    回答轮的文字增量边收边 yield（{"type":"delta_text","text":...}），
    结束后 yield {"type":"finish",...,"answer":完整回答}。
    工具轮如有少量说明文字也会流出（保留在最终 answer 之前的展示区）。
    """
    if not tools:
        async for chunk in stream_llm_text(messages, max_tokens=4000, temperature=0.2, purpose="agent"):
            yield chunk
        return
    working = list(messages)
    rounds = 0
    executed: list[dict[str, Any]] = []
    final_answer = ""
    final_usage = None
    final_provider = ""
    final_reason = "stop"
    while rounds < max_rounds:
        content = ""
        tool_calls: list[dict[str, Any]] = []
        provider = ""
        usage = None
        round_errors: list[str] = []
        async for chunk in stream_llm_with_tools(working, tools, purpose="agent_tools"):
            if chunk["type"] == "delta_text":
                content += chunk["text"]
                yield {"type": "delta_text", "text": chunk["text"]}
            elif chunk["type"] == "delta" and chunk.get("reasoning"):
                # 思考流原样透传，不进 content：它不是回答的一部分，
                # 但它是「现在到底在干什么」唯一的真实信号。
                yield {"type": "delta", "text": "", "reasoning": chunk["reasoning"]}
            elif chunk["type"] == "reset":
                content = ""
                yield chunk
            elif chunk["type"] == "round_done":
                content = chunk.get("content") or ""
                tool_calls = chunk.get("tool_calls") or []
                provider = chunk.get("provider", "")
                usage = chunk.get("usage")
            elif chunk["type"] == "error":
                # 单个 provider 失败时 stream_llm_with_tools 会继续尝试下一个；
                # 这里不能提前 return，否则 failover 被截断成「LLM 未返回内容」。
                # 记录错误继续等 round_done 或最终 error。
                round_errors.append(str(chunk.get("message") or ""))
        if not tool_calls:
            final_answer = content or final_answer
            final_usage = usage
            final_provider = provider
            if not content and round_errors:
                log.warning("Agent %s 工具轮无内容：%s", project_id, "；".join(round_errors)[:300])
            break
        working.append({"role": "assistant", "content": content, "tool_calls": tool_calls})
        # 开工事件：以前只有「完成/失败」，一次要跑十几秒的抓取期间页面上一片空白，
        # 看起来和卡死没区别。先把这一轮准备调的工具报出去。
        for pending_call in tool_calls[:12]:
            pending_name = str((pending_call.get("function") or {}).get("name") or "")
            yield {
                "type": "event",
                "kind": "tool_start",
                "tool": pending_name,
                "message": f"{REACT_TOOL_LABELS.get(pending_name) or ('调用 ' + pending_name)}…",
            }
        semaphore = asyncio.Semaphore(AGENT_MAX_PARALLEL_TOOL_CALLS)

        async def _run_one(tool_call: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
            fn = tool_call.get("function") or {}
            name = str(fn.get("name") or "")
            raw = fn.get("arguments")
            try:
                arguments = json.loads(raw or "{}") if isinstance(raw, str) else (raw or {})
            except (TypeError, ValueError):
                arguments = {}
            if not isinstance(arguments, dict):
                arguments = {}
            async with semaphore:
                try:
                    result = await asyncio.wait_for(
                        asyncio.to_thread(functools.partial(execute_react_tool, name, arguments, cache=tool_cache)),
                        timeout=AGENT_TOOL_TIMEOUT_SECONDS,
                    )
                except asyncio.TimeoutError:
                    log.warning("Agent %s 工具 %s 超时（%ss）", project_id, name, AGENT_TOOL_TIMEOUT_SECONDS)
                    result = {"ok": False, "error": f"{name} 超过 {AGENT_TOOL_TIMEOUT_SECONDS} 秒未返回，已放弃本次调用，请换一个工具或直接基于已有信息作答"}
                except Exception as exc:
                    log.warning("Agent %s 工具 %s 异常：%s", project_id, name, exc, exc_info=True)
                    result = {"ok": False, "error": f"{name} 执行异常：{clip(str(exc), 300)}"}
            return str(tool_call.get("id") or ""), name, result

        outcomes = await asyncio.gather(*(_run_one(item) for item in tool_calls[:12]))
        for call_id, name, result in outcomes:
            executed.append({"tool": name, "ok": bool(result.get("ok")), "error": clip(str(result.get("error") or ""), 200)})
            add_agent_run_event(
                run_id,
                "agent_tool_call",
                f"{agent_display_name(project_id)} 调用工具 {name}。",
                level="info" if result.get("ok") else "warning",
                metadata={"tool": name, "result_ok": bool(result.get("ok")), "error": clip(str(result.get("error") or ""), 200)},
            )
            working.append({"role": "tool", "tool_call_id": call_id, "content": json.dumps(result, ensure_ascii=False)})
            # 过程反馈：工具执行完立刻把结果状态推给前端，回答期间不再像卡死。
            action_label = REACT_TOOL_LABELS.get(name) or f"调用 {name}"
            yield {
                "type": "event",
                "kind": "tool",
                "tool": name,
                "ok": bool(result.get("ok")),
                "message": f"{action_label}{'完成' if result.get('ok') else '失败，继续'}" + (f" · {clip(str(result.get('error') or ''), 60)}" if not result.get("ok") else ""),
            }
        rounds += 1
    if not final_answer:
        # 工具轮次用尽却还没写出结论：再要一次不带工具的收敛回答（流式）。
        # stream_llm_text 的文本增量 chunk 类型是 "delta"（不是 "delta_text"），
        # 判断错了 final_answer 永远是空——工具轮越多越容易触发
        # 「LLM 未返回内容」。这里必须按 "delta" 收集。
        # 内部 finish 不转发：react loop 最后统一发带完整 answer 的 finish，
        # 否则上层会先收到一个没有 answer 的空 finish。
        async for chunk in stream_llm_text(working, max_tokens=4000, temperature=0.2, purpose="agent"):
            if chunk["type"] == "delta":
                final_answer += chunk.get("text") or ""
                yield chunk
            elif chunk["type"] == "reset":
                final_answer = ""
                yield chunk
            elif chunk["type"] == "finish":
                final_usage = chunk.get("usage")
                final_provider = chunk.get("provider", "")
                # 透传真实 reason（length_capped 等），不再硬写 stop——
                # 否则截断连信号都没有，前端看到的是一次正常完成。
                final_reason = str(chunk.get("reason") or "stop")
            elif chunk["type"] == "error":
                yield chunk
    if not final_answer:
        yield {"type": "error", "message": "LLM 未返回内容，请稍后重试。", "provider": final_provider}
        return
    yield {"type": "finish", "reason": final_reason, "usage": final_usage, "provider": final_provider, "answer": final_answer, "tool_calls": executed, "rounds": rounds}


async def run_agent_react_loop(
    *,
    project_id: str,
    run_id: str,
    messages: list[dict[str, Any]],
    tools: list[dict[str, Any]],
    tool_cache: dict[str, Any] | None = None,
    max_rounds: int = AGENT_MAX_TOOL_ROUNDS,
    queue_task_id: int = 0,
) -> dict[str, Any]:
    """跑一轮 ReAct：模型要工具就真执行，结果回喂，直到它给出结论。

    抽成公用函数的理由是一条真实的能力断层：这段循环原本只长在总调度的子
    Agent 分支里。从工作台问「市场怎么样」，市场 Agent 会真的去调 market_read；
    可是从市场项目页直接跟同一个 Agent 说话，走的是另一条代码路径——一次
    call_llm，一个工具都没有，只能对着一份可能已经过期的只读快照猜。同一个
    Agent 换个入口就少了半条腿，而项目页恰恰是最常用的入口。

    返回 {"answer": str, "tool_calls": [...], "rounds": int}；
    每次工具调用都会写进 run 的事件流，回放里能看到它到底查了什么。
    """
    answer = ""
    rounds = 0
    executed: list[dict[str, Any]] = []
    if not tools:
        return {"answer": "", "tool_calls": executed, "rounds": 0}
    working = list(messages)
    while rounds < max_rounds:
        body = await call_llm_with_tools(working, tools)
        reply = ((body.get("choices") or [{}])[0]).get("message") or {}
        content = str(reply.get("content") or "").strip()
        tool_calls = reply.get("tool_calls") or []
        if content:
            answer = content
        if not tool_calls:
            break
        working.append({"role": "assistant", "content": content, "tool_calls": tool_calls})
        semaphore = asyncio.Semaphore(AGENT_MAX_PARALLEL_TOOL_CALLS)

        async def _run_one(tool_call: dict[str, Any]) -> tuple[str, str, dict[str, Any]]:
            fn = tool_call.get("function") or {}
            name = str(fn.get("name") or "")
            raw = fn.get("arguments")
            try:
                arguments = json.loads(raw or "{}") if isinstance(raw, str) else (raw or {})
            except (TypeError, ValueError):
                arguments = {}
            if not isinstance(arguments, dict):
                arguments = {}
            async with semaphore:
                try:
                    result = await asyncio.wait_for(
                        asyncio.to_thread(functools.partial(execute_react_tool, name, arguments, cache=tool_cache,
                                                            project_id=project_id, run_id=run_id)),
                        timeout=AGENT_TOOL_TIMEOUT_SECONDS,
                    )
                except asyncio.TimeoutError:
                    log.warning("Agent %s 工具 %s 超时（%ss）", project_id, name, AGENT_TOOL_TIMEOUT_SECONDS)
                    result = {"ok": False, "error": f"{name} 超过 {AGENT_TOOL_TIMEOUT_SECONDS} 秒未返回，已放弃本次调用，请换一个工具或直接基于已有信息作答"}
                except Exception as exc:  # noqa: BLE001 - 单个工具失败要转成结果回喂，不能拖垮整轮
                    log.warning("Agent %s 工具 %s 异常：%s", project_id, name, exc, exc_info=True)
                    result = {"ok": False, "error": f"{name} 执行异常：{clip(str(exc), 300)}"}
            return str(tool_call.get("id") or ""), name, result

        # 每轮工具跑完之后看一眼有没有人往这个任务里插消息。放在这里是因为
        # 这是循环里唯一一个「上一步已结束、下一步还没定」的位置——插进来的
        # 指令能影响接下来调什么工具，而不是等它跑完才被看到。
        if queue_task_id:
            for extra in await asyncio.to_thread(consume_agent_queue_messages, queue_task_id):
                working.append({"role": "user", "content": f"（任务进行中追加的指令）{extra}"})
                add_agent_run_event(run_id, "queue_message", f"任务进行中收到追加指令：{clip(extra, 120)}", level="info")
            # 同一位置查取消：用户在队列页点了取消后，运行中的任务也能在
            # 本轮工具之间停下来，而不是只能干等（最坏 4 轮 × 60 秒）。
            if await asyncio.to_thread(agent_queue_task_cancelled, queue_task_id):
                add_agent_run_event(run_id, "cancelled", "任务已被取消，停止后续工具调用。", level="warning")
                return {"answer": "（任务已取消）", "tool_calls": executed, "rounds": rounds, "cancelled": True}
        outcomes = await asyncio.gather(*(_run_one(item) for item in tool_calls[:12]))
        for call_id, name, result in outcomes:
            executed.append({"tool": name, "ok": bool(result.get("ok")), "error": clip(str(result.get("error") or ""), 200)})
            add_agent_run_event(
                run_id,
                "agent_tool_call",
                f"{agent_display_name(project_id)} 调用工具 {name}。",
                level="info" if result.get("ok") else "warning",
                metadata={"tool": name, "result_ok": bool(result.get("ok")), "error": clip(str(result.get("error") or ""), 200)},
            )
            working.append({"role": "tool", "tool_call_id": call_id, "content": json.dumps(result, ensure_ascii=False)})
        rounds += 1
    if not answer:
        # 工具轮次用尽却还没写出结论：再要一次不带工具的收敛回答，
        # 而不是把「汇总中」这种半成品当作最终结果返回。
        add_agent_run_event(run_id, "react_forced_summary", f"{agent_display_name(project_id)} 用满 {max_rounds} 轮工具仍未给出结论，改为强制收敛作答。", level="warning")
        try:
            answer = await call_llm(
                [*working, {"role": "user", "content": "工具调用已达上限，现在不要再调用工具。请只基于以上已获得的工具结果直接给出结论；证据不足的部分明确标注为“未验证”。"}],
                purpose="agent_forced_summary",
            )
        except Exception as exc:  # noqa: BLE001
            log.warning("Agent %s 强制收敛作答失败：%s", project_id, exc)
            answer = f"（已完成 {max_rounds} 轮工具探查，但未能形成结论：{clip(str(exc), 200)}）"
    return {"answer": answer, "tool_calls": executed, "rounds": rounds}


async def stream_project_agent(
    *,
    project_id: str,
    session: dict[str, Any],
    run: dict[str, Any],
    message: str,
    context: dict[str, Any] | None = None,
):
    """流式版项目 Agent turn：ReAct 工具轮一次性，最终回答轮流式输出，收完持久化。"""
    update_agent_run_record(run["id"], status="running", error="")
    add_agent_run_event(run["id"], "started", f"{agent_display_name(project_id)} 开始读取项目上下文。")
    try:
        requested_tools = [str(item) for item in (context or {}).get("tool_ids", []) if str(item)]
        tool_boundary = validate_agent_tool_requests([project_id], requested_tools)
        if not tool_boundary["valid"]:
            raise HTTPException(400, f"请求的工具不在 {agent_display_name(project_id)} 能力声明中：{'、'.join(tool_boundary['rejected'])}")
        history = list_agent_messages(session["id"], limit=MAX_CONVERSATION_MESSAGES * 2)
        source_message = next((item for item in reversed(history) if item.get("role") == "user" and item.get("content") == message), None)
        memory_updates = learn_memories_from_message(
            message,
            project_id=project_id,
            source_type="agent_message",
            source_id=str((source_message or {}).get("id") or ""),
        )
        memory_context = memory_context_for_llm(project_id, message)
        project_context = agent_project_context(project_id)
        context_text = clip_for_llm(json.dumps(redact_agent_context(project_context), ensure_ascii=False), 16_000)
        messages = [
            {"role": "system", "content": child_agent_system(project_id) + "这是一个可持续的项目 Agent 会话。记住前面对话中的决定，但每次以当前项目上下文为准；如果用户的问题需要另一个项目，明确建议交接而不是假装拥有对方数据。"},
            {"role": "system", "content": f"本轮项目上下文（只读，可能有数据时间）：\n{context_text}"},
        ]
        if memory_context["text"]:
            messages.append({"role": "system", "content": f"用户长期记忆：\n{memory_context['text']}"})
        messages.extend({"role": item["role"], "content": item["content"]} for item in history[-MAX_CONVERSATION_MESSAGES:])
        project_tools = subagent_tool_schemas(project_id)
        tool_calls: list[dict[str, Any]] = []
        if project_tools:
            messages.insert(1, {
                "role": "system",
                "content": (
                    "你可以调用工具获取真实数据后再回答；工具结果是回答的事实依据，不要编造，也不要把快照里的旧数据当成当前值。"
                    f"可用工具：{'、'.join(item['function']['name'] for item in project_tools)}。"
                    "涉及当前状态、额度、行情、网页内容、收件箱、知识库检索等场景，先调工具再下结论。"
                ),
            })
        add_agent_run_event(run["id"], "llm_started", "正在调用全局 LLM。", metadata={"model": llm_settings().get("model", ""), "tools": len(project_tools)})
        collected: list[str] = []
        final_answer = ""
        provider = ""
        usage = None
        if project_tools:
            async for chunk in stream_agent_react_loop(
                project_id=project_id,
                run_id=run["id"],
                messages=messages,
                tools=project_tools,
                tool_cache={},
            ):
                if chunk["type"] == "delta_text":
                    collected.append(chunk["text"])
                    yield chunk
                elif chunk["type"] == "delta":
                    yield chunk
                elif chunk["type"] == "reset":
                    collected.clear()
                    final_answer = ""
                    yield chunk
                elif chunk["type"] == "finish":
                    provider = chunk.get("provider", "")
                    usage = chunk.get("usage")
                    tool_calls = chunk.get("tool_calls") or []
                    # 工具轮用尽后的收敛回答只存在于 finish.answer（react loop
                    # 内部已按 "delta" 收集），上层不能只靠 delta_text。
                    final_answer = str(chunk.get("answer") or "")
                elif chunk["type"] == "event":
                    # 工具执行过程反馈：透传给前端显示"正在搜索…/正在抓取…"。
                    yield chunk
                elif chunk["type"] == "error":
                    yield chunk
        else:
            async for chunk in stream_llm_text(messages, max_tokens=4000, temperature=0.25, purpose="agent"):
                if chunk["type"] == "delta":
                    if chunk.get("text"):
                        collected.append(chunk["text"])
                    yield chunk
                elif chunk["type"] == "reset":
                    collected.clear()
                    yield chunk
                elif chunk["type"] == "finish":
                    provider = chunk.get("provider", "")
                    usage = chunk.get("usage")
                elif chunk["type"] == "error":
                    yield chunk
        answer = (final_answer or "".join(collected)).strip()
        if not answer:
            update_agent_run_record(run["id"], status="failed", error="LLM 未返回内容")
            add_agent_run_event(run["id"], "failed", "项目 Agent 未返回内容。", level="error")
            yield {"type": "error", "message": "LLM 未返回内容，请稍后重试。", "provider": provider}
            return
        add_agent_run_event(run["id"], "llm_succeeded", "全局 LLM 已返回结果。", level="success", metadata={"tool_calls": len(tool_calls)})
        actions = materialize_agent_actions(project_id, message, answer, parent_run_id=run["id"])
        trace = agent_context_result_metadata({"project_context": project_context, "request_context": context or {}})
        execution_plan = build_agent_execution_plan(
            project_id,
            message,
            intent=str((context or {}).get("intent") or ""),
            requested_tools=tool_boundary["accepted"],
            status="partial" if any(action.get("status") == "failed" for action in actions) else "succeeded",
        )
        execution_plan["tool_calls"] = tool_calls
        execution_plan["tools_used"] = list(dict.fromkeys(item["tool"] for item in tool_calls))
        result_contract = agent_result_contract(
            project_id,
            answer,
            actions=actions,
            run_id=run["id"],
            session_id=session["id"],
            execution_plan=execution_plan,
            memory_refs=memory_context["refs"],
            memory_updates=memory_updates,
            memory_context_stats=memory_context["stats"],
            **trace,
        )
        assistant_message = add_agent_message(run["session_id"], "assistant", answer, {"actions": actions, "result_contract": result_contract, "run_id": run["id"], "memory_refs": memory_context["refs"], "memory_updates": memory_updates})
        session = update_agent_session_summary(
            session["id"],
            {"last_answer": clip(answer, 1200), "last_actions": actions, "last_result_contract": result_contract, "last_run_id": run["id"], "context_source": project_context.get("project_context", {}).get("source", ""), "last_memory_ids": [item["id"] for item in memory_context["items"]]},
        ) or session
        final_status = "partial" if any(action.get("status") == "failed" for action in actions) else "succeeded"
        result = {"session_id": session["id"], "message_id": assistant_message.get("id"), "answer": answer, "actions": actions, "result_contract": result_contract, "memory_refs": memory_context["refs"], "memory_updates": memory_updates, "memory_context": memory_context["stats"]}
        updated_run = update_agent_run_record(run["id"], status=final_status, result=result, error="") or run
        add_agent_run_event(
            run["id"],
            final_status,
            "对话完成。" if final_status == "succeeded" else "对话完成，但至少一个本地动作失败。",
            level="success" if final_status == "succeeded" else "warning",
            metadata={"actions": len(actions)},
        )
        yield {"type": "finish", "reason": "stop", "usage": usage, "provider": provider, "answer": answer, "session_id": session["id"], "message_id": assistant_message.get("id"), "actions": actions, "result_contract": result_contract, "memory_updates": memory_updates, "agent": agent_detail(project_id, llm_ready=True)}
    except Exception as exc:
        update_agent_run_record(run["id"], status="failed", error=clip(str(exc), 500))
        add_agent_run_event(run["id"], "failed", f"项目 Agent 失败：{clip(str(exc), 200)}", level="error")
        yield {"type": "error", "message": clip(str(exc), 300), "provider": ""}


async def run_project_agent(
    *,
    project_id: str,
    session: dict[str, Any],
    run: dict[str, Any],
    message: str,
    context: dict[str, Any] | None = None,
    queue_task_id: int = 0,
) -> dict[str, Any]:
    """Execute one persistent project-Agent turn and leave an audit trail."""
    update_agent_run_record(run["id"], status="running", error="")
    add_agent_run_event(run["id"], "started", f"{agent_display_name(project_id)} 开始读取项目上下文。")
    try:
        requested_tools = [str(item) for item in (context or {}).get("tool_ids", []) if str(item)]
        tool_boundary = validate_agent_tool_requests([project_id], requested_tools)
        if not tool_boundary["valid"]:
            raise HTTPException(400, f"请求的工具不在 {agent_display_name(project_id)} 能力声明中：{'、'.join(tool_boundary['rejected'])}")
        history = list_agent_messages(session["id"], limit=MAX_CONVERSATION_MESSAGES * 2)
        source_message = next((item for item in reversed(history) if item.get("role") == "user" and item.get("content") == message), None)
        memory_updates = learn_memories_from_message(
            message,
            project_id=project_id,
            source_type="agent_message",
            source_id=str((source_message or {}).get("id") or ""),
        )
        memory_context = memory_context_for_llm(project_id, message)
        project_context = agent_project_context(project_id)
        context_text = clip_for_llm(json.dumps(redact_agent_context(project_context), ensure_ascii=False), 16_000)
        messages = [
            {"role": "system", "content": child_agent_system(project_id) + "这是一个可持续的项目 Agent 会话。记住前面对话中的决定，但每次以当前项目上下文为准；如果用户的问题需要另一个项目，明确建议交接而不是假装拥有对方数据。"},
            {"role": "system", "content": f"本轮项目上下文（只读，可能有数据时间）：\n{context_text}"},
        ]
        if memory_context["text"]:
            messages.append({"role": "system", "content": f"用户长期记忆：\n{memory_context['text']}"})
        messages.extend({"role": item["role"], "content": item["content"]} for item in history[-MAX_CONVERSATION_MESSAGES:])
        # 项目页直接对话也走 ReAct：只读快照会滞后，问「现在怎么样」时必须
        # 让 Agent 真去调工具取当下的数据，而不是照着快照复述。工具边界仍然是
        # 这个项目自己声明的那一份，和总调度路径完全一致。
        project_tools = subagent_tool_schemas(project_id)
        tool_calls: list[dict[str, Any]] = []
        if project_tools:
            messages.insert(1, {
                "role": "system",
                "content": (
                    "你可以调用工具获取真实数据后再回答；工具结果是回答的事实依据，不要编造，也不要把快照里的旧数据当成当前值。"
                    f"可用工具：{'、'.join(item['function']['name'] for item in project_tools)}。"
                    "涉及当前状态、额度、行情、网页内容、收件箱、知识库检索等场景，先调工具再下结论。"
                ),
            })
        add_agent_run_event(run["id"], "llm_started", "正在调用全局 LLM。", metadata={"model": llm_settings().get("model", ""), "tools": len(project_tools)})
        if project_tools:
            loop_result = await run_agent_react_loop(
                project_id=project_id,
                run_id=run["id"],
                messages=messages,
                tools=project_tools,
                tool_cache={},
                queue_task_id=queue_task_id,
            )
            answer = loop_result["answer"]
            tool_calls = loop_result["tool_calls"]
        else:
            answer = await call_llm(messages, max_tokens=4000, temperature=0.25)
        add_agent_run_event(run["id"], "llm_succeeded", "全局 LLM 已返回结果。", level="success", metadata={"tool_calls": len(tool_calls)})
        actions = materialize_agent_actions(project_id, message, answer, parent_run_id=run["id"])
        trace = agent_context_result_metadata({"project_context": project_context, "request_context": context or {}})
        execution_plan = build_agent_execution_plan(
            project_id,
            message,
            intent=str((context or {}).get("intent") or ""),
            requested_tools=tool_boundary["accepted"],
            status="partial" if any(action.get("status") == "failed" for action in actions) else "succeeded",
        )
        # 把「这轮实际调了哪些工具」记进计划里：回放时能看出结论是查出来的
        # 还是模型自己想出来的，这是判断可信度最直接的一个信号。
        execution_plan["tool_calls"] = tool_calls
        execution_plan["tools_used"] = list(dict.fromkeys(item["tool"] for item in tool_calls))
        result_contract = agent_result_contract(
            project_id,
            answer,
            actions=actions,
            run_id=run["id"],
            session_id=session["id"],
            execution_plan=execution_plan,
            memory_refs=memory_context["refs"],
            memory_updates=memory_updates,
            memory_context_stats=memory_context["stats"],
            **trace,
        )
        assistant_message = add_agent_message(run["session_id"], "assistant", answer, {"actions": actions, "result_contract": result_contract, "run_id": run["id"], "memory_refs": memory_context["refs"], "memory_updates": memory_updates})
        session = update_agent_session_summary(
            session["id"],
            {"last_answer": clip(answer, 1200), "last_actions": actions, "last_result_contract": result_contract, "last_run_id": run["id"], "context_source": project_context.get("project_context", {}).get("source", ""), "last_memory_ids": [item["id"] for item in memory_context["items"]]},
        ) or session
        final_status = "partial" if any(action.get("status") == "failed" for action in actions) else "succeeded"
        result = {"session_id": session["id"], "message_id": assistant_message.get("id"), "answer": answer, "actions": actions, "result_contract": result_contract, "memory_refs": memory_context["refs"], "memory_updates": memory_updates, "memory_context": memory_context["stats"]}
        updated_run = update_agent_run_record(run["id"], status=final_status, result=result, error="") or run
        add_agent_run_event(
            run["id"],
            final_status,
            "对话完成。" if final_status == "succeeded" else "对话完成，但至少一个本地动作失败。",
            level="success" if final_status == "succeeded" else "warning",
            metadata={"actions": len(actions)},
        )
        return {
            "run": updated_run,
            "session": session,
            "message": assistant_message,
            "messages": list_agent_messages(session["id"], limit=40),
            "actions": actions,
            "result_contract": result_contract,
            "memory_refs": memory_context["refs"],
            "memory_updates": memory_updates,
            "agent": agent_detail(project_id, llm_ready=True),
            "links": project_link_summary(project_id),
        }
    except httpx.HTTPStatusError as exc:
        error = f"上游返回 {exc.response.status_code}：{clip(exc.response.text, 500)}"
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", f"{agent_display_name(project_id)} 调用失败：{error}", level="error")
        raise HTTPException(502, f"{agent_display_name(project_id)} 调用失败：{error}") from exc
    except HTTPException as exc:
        error = clip(str(exc.detail or exc), 800)
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", f"{agent_display_name(project_id)} 请求被能力边界拦截：{error}", level="error")
        raise
    except Exception as exc:
        error = str(exc)
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", f"{agent_display_name(project_id)} 执行失败：{error}", level="error")
        raise HTTPException(502, f"{agent_display_name(project_id)} 调用失败：{error}") from exc


def handoff_title(item: dict[str, Any], prefix: str = "") -> str:
    content = next((line.strip() for line in str(item.get("description") or item.get("title") or "").splitlines() if line.strip()), "未命名交接")
    return clip(f"{prefix}{content}", 100)


async def run_inbox_handoff_work_item(project_id: str, item: dict[str, Any]) -> dict[str, Any]:
    """Execute and audit a confirmed Inbox → Knowledge/Document handoff."""
    item_id = int(item["id"])
    session = create_agent_session(project_id, f"交接：{clip(item.get('title', '未命名工作项'), 90)}")
    handoff_message = (
        "这是一个来自快速收件箱的已确认交接，请把它当作当前项目 Agent 的正式任务处理。\n\n"
        f"来源 Agent：{item.get('source_agent_name', item.get('source_project', '工作台'))}\n"
        f"工作项：{item.get('title', '未命名工作项')}\n"
        f"任务内容：\n{item.get('description', '')}\n\n"
        "请基于当前项目上下文，输出事实、判断、缺口和下一步；不要把未验证内容写成确定事实。"
    )
    add_agent_message(session["id"], "user", handoff_message, {"source": "work_item", "work_item_id": item_id, "source_project": item.get("source_project", "")})
    run = create_agent_run_record(
        project_id=project_id,
        session_id=session["id"],
        parent_run_id=str(item.get("claimed_run_id") or ""),
        kind="handoff_knowledge" if project_id == "knowledge" else "handoff_document",
        title=clip(item.get("title", "交接工作项"), 240),
        request={"work_item_id": item_id, "source_project": item.get("source_project", ""), "message": handoff_message},
        max_attempts=2,
        attempt=2 if item.get("claimed_run_id") else 1,
    )
    update_work_item_record(item_id, {"status": "running", "claimed_at": now_iso(), "claimed_run_id": run["id"], "last_error": ""})
    artifact = None
    answer = ""
    assistant_message = None
    try:
        if project_id == "knowledge":
            result = await run_project_agent(project_id=project_id, session=session, run=run, message=handoff_message, context={"source": "inbox_handoff", "work_item_id": item_id})
            session = result.get("session") or session
            answer = str(result.get("message", {}).get("content", "")).strip()
            note = write_knowledge_note(
                handoff_title(item, "收件箱沉淀："),
                f"> 来源：快速收件箱 #{item_id}\n> 原始内容：{clip(str(item.get('description') or ''), 600)}\n\n{answer}",
                metadata={"source_inbox_id": item_id, "source_work_item_id": item_id, "handoff_run_id": run["id"], "source_project": "inbox"},
                artifact_kind="inbox_handoff_note",
            )
            artifact = note.get("artifact")
            assistant_message = result.get("message")
            update_agent_run_record(run["id"], status="succeeded", result={"answer": answer, "artifact_id": artifact.get("id") if artifact else None, "session_id": session["id"], "source_work_item_id": item_id}, error="")
            add_agent_run_event(run["id"], "artifact_produced", "知识库 Agent 已生成本地 Markdown 笔记。", level="success", metadata={"artifact_id": artifact.get("id") if artifact else None})
        else:
            update_agent_run_record(run["id"], status="running", error="")
            add_agent_run_event(run["id"], "started", "文档工厂 Agent 开始把收件箱内容加工为版本化工作草稿。")
            add_agent_run_event(run["id"], "llm_started", "正在调用全局 LLM 生成文档草稿。")
            answer = await call_llm(
                [
                    {"role": "system", "content": "你是本地文档工厂 Agent。把收件箱内容加工成中文 Markdown 工作草稿。不得编造事实；必须分开写：目标、已知信息、待确认问题、建议下一步。明确标注这不是已经批准的正式交付。"},
                    {"role": "user", "content": f"来源收件箱 #{item_id}\n{item.get('description', '')}"},
                ],
                max_tokens=4000,
                temperature=0.2,
            )
            add_agent_run_event(run["id"], "llm_succeeded", "文档草稿已生成。", level="success")
            assistant_message = add_agent_message(session["id"], "assistant", answer, {"run_id": run["id"], "source_work_item_id": item_id})
            session = update_agent_session_summary(session["id"], {"last_answer": clip(answer, 1200), "last_run_id": run["id"], "source_work_item_id": item_id}) or session
            previous = next((candidate for candidate in list_artifacts("doc-factory") if candidate.get("metadata", {}).get("source_work_item_id") == item_id), None)
            version = int((previous or {}).get("metadata", {}).get("version") or 0) + 1
            title = handoff_title(item, "收件箱交付：")
            output_name = f"{datetime.now().strftime('%Y%m%d-%H%M%S')}-v{version}-{safe_filename(title, '收件箱文档')}.md"
            output_path = OUTPUTS_DIR / output_name
            output_path.write_text(answer.rstrip() + "\n", encoding="utf-8")
            artifact = register_artifact_safely(
                project_id="doc-factory",
                name=output_name,
                path=str(output_path),
                kind="inbox_handoff_document",
                metadata={"title": title, "version": version, "source_inbox_id": item_id, "source_work_item_id": item_id, "source_project": "inbox", "source_name": f"快速收件箱 #{item_id}", "handoff_run_id": run["id"], "draft_only": True},
            )
            if previous and artifact:
                create_relation_record(from_type="artifact", from_id=str(previous["id"]), to_type="artifact", to_id=str(artifact["id"]), relation_type="version_of", metadata={"project_id": "doc-factory", "version": version, "source_work_item_id": item_id})
            update_agent_run_record(run["id"], status="succeeded", result={"answer": answer, "artifact_id": artifact.get("id") if artifact else None, "session_id": session["id"]}, error="")
            add_agent_run_event(run["id"], "artifact_produced", "文档工厂 Agent 已保存版本化工作草稿。", level="success", metadata={"artifact_id": artifact.get("id") if artifact else None, "version": version})
        if artifact:
            create_relation_record(from_type="work_item", from_id=str(item_id), to_type="artifact", to_id=str(artifact.get("id")), relation_type="produced", metadata={"project_id": project_id, "source_inbox_id": item_id, "agent_run_id": run["id"]})
            create_relation_record(from_type="agent_run", from_id=run["id"], to_type="artifact", to_id=str(artifact.get("id")), relation_type="produced", metadata={"project_id": project_id, "source_work_item_id": item_id})
        relation = create_relation_record(from_type="work_item", from_id=str(item_id), to_type="agent_run", to_id=run["id"], relation_type="processed_by", metadata={"project_id": project_id, "status": "done", "artifact_id": artifact.get("id") if artifact else None})
        result_payload = {"agent_run_id": run["id"], "answer": answer, "artifact": artifact, "source_inbox_id": item_id}
        updated_item = update_work_item_record(item_id, {"status": "done", "result_json": json.dumps(result_payload, ensure_ascii=False), "completed_at": now_iso(), "last_error": ""}) or item
        notification = create_notification_record(title=f"{agent_display_name(project_id)}已完成收件箱交接", body=f"{item.get('title', '交接工作项')} · 已生成{'知识笔记' if project_id == 'knowledge' else '版本化文档草稿'}，结果可回溯。", project_id=project_id, kind="agent_result", level="success", href=project_href(project_id), event_key=f"work-item-run:{item_id}:{run['id']}", dedupe_seconds=0)
        return {"ok": True, "work_item": updated_item, "run": get_agent_run(run["id"]) or run, "relation": relation, "artifact": artifact, "notification": notification, "session": session, "message": assistant_message, "answer": answer, "messages": list_agent_messages(session["id"], limit=40), "agent": agent_detail(project_id, llm_ready=True), "links": project_link_summary(project_id)}
    except HTTPException as exc:
        error = str(exc.detail)
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", error, level="error")
        update_work_item_record(item_id, {"status": "failed", "completed_at": now_iso(), "last_error": error})
        try:
            relation = create_relation_record(
                from_type="work_item",
                from_id=str(item_id),
                to_type="agent_run",
                to_id=run["id"],
                relation_type="processed_by",
                metadata={"project_id": project_id, "status": "failed", "error": error},
            )
            create_notification_record(
                title=f"{agent_display_name(project_id)}收件箱交接失败",
                body=f"{item.get('title', '交接工作项')} · {error}",
                project_id=project_id,
                kind="agent_result",
                level="error",
                href=project_href(project_id),
                event_key=f"work-item-run:{item_id}:{run['id']}",
                dedupe_seconds=0,
            )
        except Exception:
            log.debug("忽略异常（run_inbox_handoff_work_item）", exc_info=True)
        raise
    except Exception as exc:
        error = str(exc)
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", f"收件箱交接失败：{error}", level="error")
        update_work_item_record(item_id, {"status": "failed", "completed_at": now_iso(), "last_error": error})
        try:
            create_relation_record(
                from_type="work_item",
                from_id=str(item_id),
                to_type="agent_run",
                to_id=run["id"],
                relation_type="processed_by",
                metadata={"project_id": project_id, "status": "failed", "error": error},
            )
            create_notification_record(title=f"{agent_display_name(project_id)}收件箱交接失败", body=f"{item.get('title', '交接工作项')} · {error}", project_id=project_id, kind="agent_result", level="error", href=project_href(project_id), event_key=f"work-item-run:{item_id}:{run['id']}", dedupe_seconds=0)
        except Exception:
            log.debug("忽略异常（run_inbox_handoff_work_item）", exc_info=True)
        raise HTTPException(502, f"{agent_display_name(project_id)}处理交接失败：{error}") from exc


async def stream_aihot_agent_turn(
    *,
    run: dict[str, Any],
    session: dict[str, Any],
    message: str,
    chosen: list[dict[str, Any]],
):
    """流式版 AI 热点 Agent：边收边产出 SSE 事件，收完后持久化（与 run_aihot_agent_turn 同语义）。"""
    update_agent_run_record(run["id"], status="running", error="")
    add_agent_run_event(run["id"], "started", "AI 热点 Agent 开始整理所选资讯。")
    evidence = "\n\n".join(
        f"[{index}] {item.get('title')}\n来源：{item.get('source')}｜时间：{item.get('published_at')}｜重要度：{item.get('importance')}\n摘要：{item.get('description')}\n原文：{item.get('link')}"
        for index, item in enumerate(chosen, start=1)
    )
    system = (
        "你是工作台中的 AI 热点研究 Agent。只基于下方 aiHot.today 公开资讯回答，不能把新闻标题当成已验证事实。"
        "用户可能想知道哪些消息值得看、对个人效率或创业有什么启发、是否值得继续研究。"
        "请明确区分：已知信息、你的判断、需要验证的地方。给出最多 3 个可执行的下一步。"
        "如果用户要求发现商机，请优先从真实需求、目标用户、付费可能、竞争和 7 天验证切入。使用简体中文。"
    )
    try:
        history = list_agent_messages(session["id"], limit=MAX_CONVERSATION_MESSAGES * 2)
        messages = [
            {"role": "system", "content": system},
            *({"role": item["role"], "content": item["content"]} for item in history[-MAX_CONVERSATION_MESSAGES:]),
            {"role": "user", "content": f"资讯证据：\n{clip_for_llm(evidence, 18_000)}\n\n用户问题：\n{message}"},
        ]
        add_agent_run_event(run["id"], "llm_started", "正在调用全局 LLM 分析热点证据。", metadata={"items": len(chosen)})
        collected: list[str] = []
        provider = ""
        usage = None
        async for chunk in stream_llm_text(messages, max_tokens=4000, temperature=0.25, purpose="aihot"):
            if chunk["type"] == "delta":
                if chunk.get("text"):
                    collected.append(chunk["text"])
                yield chunk
            elif chunk["type"] == "reset":
                collected.clear()
                yield chunk
            elif chunk["type"] == "finish":
                provider = chunk.get("provider", "")
                usage = chunk.get("usage")
            elif chunk["type"] == "error":
                yield chunk
        answer = "".join(collected).strip()
        if not answer:
            update_agent_run_record(run["id"], status="failed", error="LLM 未返回内容")
            add_agent_run_event(run["id"], "failed", "AI 热点 Agent 未返回内容。", level="error")
            yield {"type": "error", "message": "LLM 未返回内容，请稍后重试。", "provider": provider}
            return
        add_agent_run_event(run["id"], "llm_succeeded", "热点分析已返回。", level="success")
        evidence_items = [{"id": item.get("id", ""), "type": "aihot_item", "title": item.get("title", ""), "source": item.get("source", ""), "published_at": item.get("published_at", ""), "link": item.get("link", "")} for item in chosen]
        result_contract = agent_result_contract("aihot", answer, evidence=evidence_items, source_refs=evidence_items, run_id=run["id"], session_id=session["id"])
        assistant_message = add_agent_message(session["id"], "assistant", answer, {"run_id": run["id"], "item_ids": [item.get("id") for item in chosen], "result_contract": result_contract})
        session = update_agent_session_summary(
            session["id"],
            {"last_answer": clip(answer, 1200), "last_result_contract": result_contract, "last_run_id": run["id"], "selected_items": [item.get("id") for item in chosen]},
        ) or session
        result = {"answer": answer, "items": chosen, "session_id": session["id"], "message_id": assistant_message.get("id"), "result_contract": result_contract}
        updated_run = update_agent_run_record(run["id"], status="succeeded", result=result, error="") or run
        add_agent_run_event(run["id"], "succeeded", "AI 热点 Agent 本轮完成。", level="success")
        yield {"type": "finish", "reason": "stop", "usage": usage, "provider": provider, "answer": answer, "session_id": session["id"], "message_id": assistant_message.get("id"), "result_contract": result_contract}
    except Exception as exc:
        update_agent_run_record(run["id"], status="failed", error=clip(str(exc), 500))
        add_agent_run_event(run["id"], "failed", f"AI 热点 Agent 失败：{clip(str(exc), 200)}", level="error")
        yield {"type": "error", "message": clip(str(exc), 300), "provider": ""}


async def run_aihot_agent_turn(
    *,
    run: dict[str, Any],
    session: dict[str, Any],
    message: str,
    chosen: list[dict[str, Any]],
) -> dict[str, Any]:
    """Run the AI-hotspot Agent with selected public evidence and persistence."""
    update_agent_run_record(run["id"], status="running", error="")
    add_agent_run_event(run["id"], "started", "AI 热点 Agent 开始整理所选资讯。")
    evidence = "\n\n".join(
        f"[{index}] {item.get('title')}\n来源：{item.get('source')}｜时间：{item.get('published_at')}｜重要度：{item.get('importance')}\n摘要：{item.get('description')}\n原文：{item.get('link')}"
        for index, item in enumerate(chosen, start=1)
    )
    system = (
        "你是工作台中的 AI 热点研究 Agent。只基于下方 aiHot.today 公开资讯回答，不能把新闻标题当成已验证事实。"
        "用户可能想知道哪些消息值得看、对个人效率或创业有什么启发、是否值得继续研究。"
        "请明确区分：已知信息、你的判断、需要验证的地方。给出最多 3 个可执行的下一步。"
        "如果用户要求发现商机，请优先从真实需求、目标用户、付费可能、竞争和 7 天验证切入。使用简体中文。"
    )
    try:
        history = list_agent_messages(session["id"], limit=MAX_CONVERSATION_MESSAGES * 2)
        add_agent_run_event(run["id"], "llm_started", "正在调用全局 LLM 分析热点证据。", metadata={"items": len(chosen)})
        answer = await call_llm(
            [
                {"role": "system", "content": system},
                *({"role": item["role"], "content": item["content"]} for item in history[-MAX_CONVERSATION_MESSAGES:]),
                {"role": "user", "content": f"资讯证据：\n{clip_for_llm(evidence, 18_000)}\n\n用户问题：\n{message}"},
            ],
            max_tokens=4000,
            temperature=0.25,
        )
        add_agent_run_event(run["id"], "llm_succeeded", "热点分析已返回。", level="success")
        evidence_items = [{"id": item.get("id", ""), "type": "aihot_item", "title": item.get("title", ""), "source": item.get("source", ""), "published_at": item.get("published_at", ""), "link": item.get("link", "")} for item in chosen]
        result_contract = agent_result_contract("aihot", answer, evidence=evidence_items, source_refs=evidence_items, run_id=run["id"], session_id=session["id"])
        assistant_message = add_agent_message(session["id"], "assistant", answer, {"run_id": run["id"], "item_ids": [item.get("id") for item in chosen], "result_contract": result_contract})
        session = update_agent_session_summary(
            session["id"],
            {"last_answer": clip(answer, 1200), "last_result_contract": result_contract, "last_run_id": run["id"], "selected_items": [item.get("id") for item in chosen]},
        ) or session
        result = {"answer": answer, "items": chosen, "session_id": session["id"], "message_id": assistant_message.get("id"), "result_contract": result_contract}
        updated_run = update_agent_run_record(run["id"], status="succeeded", result=result, error="") or run
        add_agent_run_event(run["id"], "succeeded", "AI 热点 Agent 本轮完成。", level="success")
        return {
            "run": updated_run,
            "session": session,
            "message": assistant_message,
            "messages": list_agent_messages(session["id"], limit=40),
            "answer": answer,
            "result_contract": result_contract,
            "items": chosen,
            "agent": agent_detail("aihot", llm_ready=True),
        }
    except httpx.HTTPStatusError as exc:
        error = f"上游返回 {exc.response.status_code}：{clip(exc.response.text, 500)}"
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", f"AI 热点 Agent 调用失败：{error}", level="error")
        raise HTTPException(502, f"AI 热点 Agent 调用失败：{error}") from exc
    except Exception as exc:
        error = str(exc)
        update_agent_run_record(run["id"], status="failed", error=error)
        add_agent_run_event(run["id"], "failed", f"AI 热点 Agent 执行失败：{error}", level="error")
        raise HTTPException(502, f"AI 热点 Agent 调用失败：{error}") from exc


async def stream_idea_agent_turn(
    *,
    run: dict[str, Any],
    session: dict[str, Any],
    message: str,
):
    """流式版想法分析 Agent：边收边产出 SSE 事件，收完后持久化。"""
    update_agent_run_record(run["id"], status="running", error="")
    add_agent_run_event(run["id"], "started", "想法分析 Agent 开始整理假设和验证路径。")
    system = (
        "你是工作台中的想法分析 Agent，负责和用户一起判断一个奇怪想法是否值得做。"
        "你不是一上来就泼冷水，也不是无条件鼓励；必须通过追问和证据逐步收敛。"
        "每轮都尽量围绕：目标用户与痛点、现有替代方案、付费或价值、获客路径、竞争壁垒、实现成本、合规风险。"
        "当信息不足时先提出不超过 3 个关键问题；当已经足够判断时，输出：\n"
        "1. 结论：值得做 / 先验证 / 暂不建议；\n"
        "2. 依据：事实与假设分开；\n"
        "3. 最小验证：7 天内能完成的动作、目标用户、成功指标；\n"
        "4. 风险与下一步。\n"
        "不要假装做过外部市场调研；没有证据就标注待验证。使用简体中文，像一个务实的产品合伙人。"
    )
    try:
        history = list_idea_messages(session["id"], limit=12)
        messages = [{"role": "system", "content": system}] + [{"role": item["role"], "content": item["content"]} for item in history]
        add_agent_run_event(run["id"], "llm_started", "正在调用全局 LLM 做想法分析。")
        collected: list[str] = []
        provider = ""
        usage = None
        async for chunk in stream_llm_text(messages, max_tokens=4000, temperature=0.3, purpose="idea-analysis"):
            if chunk["type"] == "delta":
                if chunk.get("text"):
                    collected.append(chunk["text"])
                yield chunk
            elif chunk["type"] == "reset":
                collected.clear()
                yield chunk
            elif chunk["type"] == "finish":
                provider = chunk.get("provider", "")
                usage = chunk.get("usage")
            elif chunk["type"] == "error":
                yield chunk
        answer = "".join(collected).strip()
        if not answer:
            update_agent_run_record(run["id"], status="failed", error="LLM 未返回内容")
            add_agent_run_event(run["id"], "failed", "想法分析 Agent 未返回内容。", level="error")
            yield {"type": "error", "message": "LLM 未返回内容，请稍后重试。", "provider": provider}
            return
        add_agent_run_event(run["id"], "llm_succeeded", "想法分析已返回。", level="success")
        result_contract = agent_result_contract(
            "idea-analysis",
            answer,
            source_refs=[{"type": "idea_session", "id": session["id"], "title": session.get("title", "未命名想法"), "updated_at": session.get("updated_at", "")}],
            data_as_of=session.get("updated_at", ""),
            run_id=run["id"],
            session_id=session["id"],
        )
        assistant_message = add_idea_message(session["id"], "assistant", answer)
        verdict_match = re.search(r"(值得做|先验证|暂不建议)", answer)
        summary = {
            **(session.get("summary") if isinstance(session.get("summary"), dict) else {}),
            "verdict": verdict_match.group(1) if verdict_match else "继续澄清",
            "last_answer": clip(answer, 1000),
            "last_result_contract": result_contract,
            "last_run_id": run["id"],
        }
        session = update_idea_session_summary(session["id"], summary) or session
        result = {"answer": answer, "session_id": session["id"], "message_id": assistant_message.get("id"), "verdict": summary["verdict"], "result_contract": result_contract}
        updated_run = update_agent_run_record(run["id"], status="succeeded", result=result, error="") or run
        add_agent_run_event(run["id"], "succeeded", "想法分析 Agent 本轮完成。", level="success")
        yield {"type": "finish", "reason": "stop", "usage": usage, "provider": provider, "answer": answer, "session_id": session["id"], "message_id": assistant_message.get("id"), "verdict": summary["verdict"], "result_contract": result_contract}
    except Exception as exc:
        update_agent_run_record(run["id"], status="failed", error=clip(str(exc), 500))
        add_agent_run_event(run["id"], "failed", f"想法分析 Agent 失败：{clip(str(exc), 200)}", level="error")
        yield {"type": "error", "message": clip(str(exc), 300), "provider": ""}


