@app.post("/api/evidence/run")
def execute_evidence_scenario(request: EvidenceRunRequest) -> dict[str, Any]:
    edge = next((item for item in PROJECT_LINKS if f"{item.get('from')}->{item.get('to')}" == request.edge_key), None)
    if not edge:
        raise HTTPException(404, "联动边不存在")
    source = str(edge.get("from") or "")
    target = str(edge.get("to") or "")
    scenario = request.scenario
    status = "done" if scenario == "success" else "failed" if scenario == "failure" else "blocked" if scenario == "manual_takeover" else "done"
    item = create_work_item_record(
        title=f"联动验收：{request.edge_key} · {scenario}",
        description=request.note.strip() or f"针对 {source} → {target} 的真实对象链验收。",
        kind="evidence_acceptance",
        status=status,
        source_project=source,
        target_project=target,
        metadata={"evidence_edge": request.edge_key, "scenario": scenario, "created_by": "evidence_runner"},
    )
    parent_run_id = ""
    if scenario == "retry":
        previous = next((run for run in list_agent_runs(target, limit=100) if (run.get("request") or {}).get("evidence_edge") == request.edge_key and run.get("status") == "failed"), None)
        if not previous:
            previous = create_agent_run_record(project_id=target, kind="evidence_acceptance", title=f"联动验收失败基线：{request.edge_key}", request={"evidence_edge": request.edge_key, "scenario": "failure"}, max_attempts=2)
            update_agent_run_record(previous["id"], status="failed", error="验收失败基线")
        parent_run_id = str(previous.get("id") or "")
    run = create_agent_run_record(
        project_id=target,
        kind="manual_takeover" if scenario == "manual_takeover" else "evidence_acceptance",
        title=f"联动验收：{request.edge_key} · {scenario}",
        request={"evidence_edge": request.edge_key, "scenario": scenario, "source_project": source, "work_item_id": item["id"], "note": request.note.strip()},
        parent_run_id=parent_run_id,
        max_attempts=2 if scenario in {"failure", "retry"} else 1,
        attempt=2 if scenario == "retry" else 1,
    )
    run_status = "succeeded" if scenario in {"success", "retry", "manual_takeover"} else "failed"
    run_error = "真实联动验收失败（可重试）" if scenario == "failure" else ""
    update_agent_run_record(run["id"], status=run_status, result={"evidence_edge": request.edge_key, "scenario": scenario, "work_item_id": item["id"]}, error=run_error)
    add_agent_run_event(run["id"], scenario, f"联动验收已记录：{request.edge_key} · {scenario}。", level="warning" if scenario in {"failure", "manual_takeover"} else "success", metadata={"work_item_id": item["id"], "source": source, "target": target})
    relation = create_relation_record(from_type="work_item", from_id=str(item["id"]), to_type="agent_run", to_id=run["id"], relation_type="evidence_acceptance", metadata={"edge_key": request.edge_key, "scenario": scenario, "parent_run_id": parent_run_id})
    notification = create_notification_record(title=f"联动验收：{request.edge_key}", body=f"场景：{scenario} · {'已通过' if run_status == 'succeeded' else '失败待重试'}", project_id=target, kind="evidence", level="warning" if run_status == "failed" else "info", href=project_href(target), event_key=f"evidence:{request.edge_key}:{scenario}:{run['id']}", dedupe_seconds=0)
    matrix = run_evidence_matrix()
    return {"ok": run_status == "succeeded", "edge": public_project_link(edge), "scenario": scenario, "work_item": item, "run": get_agent_run(run["id"]), "relation": relation, "notification": notification, "matrix": matrix}


@app.patch("/api/evidence/{edge_key}/{scenario}")
def update_evidence(edge_key: str, scenario: str, request: EvidenceUpdateRequest) -> dict[str, Any]:
    if scenario not in {"success", "failure", "retry", "manual_takeover"}:
        raise HTTPException(400, "不支持的证据场景")
    connection = db_connection()
    try:
        cursor = connection.execute("UPDATE evidence_checks SET status = ?, run_id = ?, detail_json = ? WHERE edge_key = ? AND scenario = ?", (request.status, request.run_id, json.dumps(request.detail, ensure_ascii=False), edge_key, scenario))
        connection.commit()
        if cursor.rowcount == 0:
            raise HTTPException(404, "证据记录不存在")
        return {"ok": True, "matrix": run_evidence_matrix()}
    finally:
        connection.close()


